const SVG_NS = 'http://www.w3.org/2000/svg';
const svgMarkupTemplateCache = new Map<string, SVGElement>();

function parsePageBridgeEventDetail<T>(detail: unknown): T | null {
  if (typeof detail === 'string') {
    try {
      return JSON.parse(detail) as T;
    } catch {
      return null;
    }
  }

  if (!detail || typeof detail !== 'object') return null;

  try {
    if ('wrappedJSObject' in detail && (detail as { wrappedJSObject?: unknown }).wrappedJSObject) {
      return parsePageBridgeEventDetail<T>((detail as { wrappedJSObject?: unknown }).wrappedJSObject);
    }
  } catch {}

  try {
    return JSON.parse(JSON.stringify(detail)) as T;
  } catch {
    return null;
  }
}

function getCustomEventDetailSafely<T>(event: Event): T | null {
  if (!(event instanceof CustomEvent)) return null;

  try {
    return event.detail as T;
  } catch {
    return null;
  }
}

function createHtmlElement<K extends keyof HTMLElementTagNameMap>(
  tagName: K,
  className?: string,
  textContent?: string,
): HTMLElementTagNameMap[K] {
  const element = document.createElement(tagName);
  if (className) element.className = className;
  if (textContent !== undefined) element.textContent = textContent;
  return element;
}

function createSvgElement<K extends keyof SVGElementTagNameMap>(
  tagName: K,
  attributes: Record<string, string> = {},
): SVGElementTagNameMap[K] {
  const element = document.createElementNS(SVG_NS, tagName);
  Object.entries(attributes).forEach(([name, value]) => {
    element.setAttribute(name, value);
  });
  return element;
}

function createSvgFromMarkup(markup: string): SVGElement {
  const cached = svgMarkupTemplateCache.get(markup);
  if (cached) return cached.cloneNode(true) as SVGElement;

  const range = document.createRange();
  range.selectNode(document.documentElement);
  const fragment = range.createContextualFragment(markup.trim());
  const svg = fragment.firstElementChild;
  if (!(svg instanceof SVGElement)) {
    return createSvgElement('svg');
  }

  const imported = svg.cloneNode(true) as SVGElement;
  svgMarkupTemplateCache.set(markup, imported);
  return imported.cloneNode(true) as SVGElement;
}

function setSvgIcon(target: Element, markup: string): void {
  target.replaceChildren(createSvgFromMarkup(markup));
}

function setButtonIconWithLabel(
  button: HTMLElement,
  iconMarkup: string,
  labelText: string,
  iconClassName = 'ytr-thumb-overlay-btn-icon',
  labelClassName = 'ytr-thumb-overlay-btn-label',
): void {
  const icon = createHtmlElement('span', iconClassName);
  setSvgIcon(icon, iconMarkup);
  const label = createHtmlElement('span', labelClassName, labelText);
  button.replaceChildren(icon, label);
}

