function setActionButtonIcon(button: HTMLButtonElement, markup: string): void {
  const icon = createHtmlElement('span', 'yt-spec-button-shape-next__icon');
  setSvgIcon(icon, markup);
  button.replaceChildren(icon);
}

function createSvgIcon(markup: string, className: string): HTMLSpanElement {
  const icon = createHtmlElement('span', className);
  setSvgIcon(icon, markup);
  return icon;
}

function extractJsonObjectAtIndex(source: string, objectStart: number): string | null {
  if (objectStart < 0 || objectStart >= source.length || source[objectStart] !== '{') return null;

  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let index = objectStart; index < source.length; index += 1) {
    const char = source[index];

    if (escaped) {
      escaped = false;
      continue;
    }

    if (inString) {
      if (char === '\\') {
        escaped = true;
      } else if (char === '"') {
        inString = false;
      }
      continue;
    }

    if (char === '"') {
      inString = true;
      continue;
    }

    if (char === '{') {
      depth += 1;
      continue;
    }

    if (char !== '}') continue;
    depth -= 1;
    if (depth === 0) {
      return source.slice(objectStart, index + 1);
    }
  }

  return null;
}

function extractJsonObjectAfterKey(source: string, key: string): string | null {
  const keyIndex = source.indexOf(key);
  if (keyIndex < 0) return null;
  let valueStart = keyIndex + key.length;
  while (valueStart < source.length && /\s/.test(source[valueStart])) {
    valueStart += 1;
  }
  if (source[valueStart] !== '{') return null;
  return extractJsonObjectAtIndex(source, valueStart);
}

function extractJsonObjectsAfterKey(source: string, key: string, maxMatches = 16): string[] {
  const results: string[] = [];
  let searchIndex = 0;

  while (results.length < maxMatches) {
    const keyIndex = source.indexOf(key, searchIndex);
    if (keyIndex < 0) break;

    let valueStart = keyIndex + key.length;
    while (valueStart < source.length && /\s/.test(source[valueStart])) {
      valueStart += 1;
    }

    if (source[valueStart] !== '{') {
      searchIndex = keyIndex + key.length;
      continue;
    }

    const object = extractJsonObjectAtIndex(source, valueStart);
    if (object) {
      results.push(object);
    }

    searchIndex = valueStart + 1;
  }

  return results;
}

function createMaterialSymbolIcon(
  ligature: string,
  className: string,
  filled = false,
): HTMLSpanElement {
  const icon = createHtmlElement('span', `ytr-material-symbols-rounded material-symbols-rounded ${className}`, ligature);
  icon.setAttribute('aria-hidden', 'true');
  icon.style.fontVariationSettings = `'FILL' ${filled ? 1 : 0}, 'wght' 500, 'GRAD' 0, 'opsz' 24`;
  return icon;
}

function setMaterialSymbolIconWithLabel(
  target: HTMLElement,
  ligature: string,
  labelText: string,
  iconClassName: string,
  labelClassName: string,
  filled = false,
): void {
  const icon = createMaterialSymbolIcon(ligature, iconClassName, filled);
  const label = createHtmlElement('span', labelClassName, labelText);
  target.replaceChildren(icon, label);
}

function resetClassicLikeIcons(): void {
  if (classicLikeIconsSyncRaf) {
    window.cancelAnimationFrame(classicLikeIconsSyncRaf);
    classicLikeIconsSyncRaf = 0;
  }

  document.querySelectorAll('.ytr-classic-like-icon-host').forEach((host) => {
    if (!(host instanceof HTMLElement)) return;
    host.classList.remove('ytr-classic-like-icon-host');
    delete host.dataset.ytrClassicKind;
    host.style.removeProperty('--ytr-classic-icon-size');

    const injectedIcon = host.querySelector(':scope > .ytr-classic-like-icon');
    if (injectedIcon) {
      injectedIcon.remove();
    }
  });
}

function syncClassicLikeIconsState(enabled: boolean): void {
  classicLikeIconsObserver?.disconnect();
  classicLikeIconsObserver = null;
  resetClassicLikeIcons();

  if (!enabled) return;

  // Classic icons are restored via CSS pseudo-elements from the old stable implementation.
  // We only need to clean legacy injected nodes left from earlier optimized builds.
}

function dispatchElementActivation(target: HTMLElement): boolean {
  const rect = target.getBoundingClientRect();
  const pointerInit: PointerEventInit = {
    bubbles: true,
    cancelable: true,
    composed: true,
    pointerType: 'mouse',
    isPrimary: true,
    button: 0,
    buttons: 1,
    clientX: rect.left + (rect.width / 2),
    clientY: rect.top + (rect.height / 2),
  };

  try {
    if (typeof window.PointerEvent === 'function') {
      target.dispatchEvent(new PointerEvent('pointerenter', pointerInit));
      target.dispatchEvent(new PointerEvent('pointerover', pointerInit));
      target.dispatchEvent(new PointerEvent('pointerdown', pointerInit));
      target.dispatchEvent(new PointerEvent('pointerup', { ...pointerInit, buttons: 0 }));
    }
  } catch {}

  try {
    target.dispatchEvent(new MouseEvent('mouseenter', { bubbles: true, cancelable: true, view: window }));
    target.dispatchEvent(new MouseEvent('mouseover', { bubbles: true, cancelable: true, view: window }));
    target.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true, view: window, button: 0, buttons: 1 }));
    target.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true, view: window, button: 0, buttons: 0 }));
    target.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window, button: 0 }));
  } catch {}

  try {
    target.click();
    return true;
  } catch {
    return false;
  }
}

function resolveClickableButtonCandidate(candidate: Element | null): HTMLElement | null {
  if (!(candidate instanceof HTMLElement)) return null;

  const nestedButton = candidate.querySelector(
    'button, [role="button"], a[role="button"], .ytp-ad-skip-button-modern, .ytp-skip-ad-button, .videoAdUiSkipButton'
  ) as HTMLElement | null;
  if (nestedButton instanceof HTMLElement) {
    return nestedButton;
  }

  const nearestButton = candidate.closest(
    'button, [role="button"], a[role="button"], .ytp-ad-skip-button-modern, .ytp-skip-ad-button, .videoAdUiSkipButton'
  ) as HTMLElement | null;
  if (nearestButton instanceof HTMLElement) {
    return nearestButton;
  }

  return candidate;
}

function ensurePageBridgeInjected(): Promise<void> {
  if (pageBridgeReadyPromise) return pageBridgeReadyPromise;

  pageBridgeReadyPromise = new Promise((resolve) => {
    const existing = document.querySelector('script[data-ytr-page-bridge="true"]') as HTMLScriptElement | null;
    if (existing) {
      if (existing.dataset.loaded === 'true') {
        resolve();
        return;
      }
      existing.addEventListener('load', () => resolve(), { once: true });
      existing.addEventListener('error', () => resolve(), { once: true });
      return;
    }

    const script = createHtmlElement('script') as HTMLScriptElement;
    script.src = browser.runtime.getURL('ytr-page-bridge.js');
    script.async = false;
    script.dataset.ytrPageBridge = 'true';
    script.addEventListener('load', () => {
      script.dataset.loaded = 'true';
      resolve();
    }, { once: true });
    script.addEventListener('error', () => resolve(), { once: true });
    (document.head || document.documentElement).appendChild(script);
  });

  return pageBridgeReadyPromise;
}

async function requestPageBridge<T extends PageBridgeResponse>(
  type: string,
  payload: Record<string, unknown> = {},
  timeoutMs = 1200,
): Promise<T | null> {
  await ensurePageBridgeInjected();

  return await new Promise((resolve) => {
    const requestId = `ytr-${type}-${Math.random().toString(36).slice(2)}`;
    const timeout = window.setTimeout(() => {
      window.removeEventListener(PAGE_BRIDGE_RESPONSE_EVENT, handleResponse as EventListener);
      resolve(null);
    }, timeoutMs);

    const handleResponse = (event: Event) => {
      const detail = parsePageBridgeEventDetail<PageBridgeResponse>(
        getCustomEventDetailSafely<PageBridgeResponse | string>(event),
      );
      if (!detail || detail.requestId !== requestId) return;
      clearTimeout(timeout);
      window.removeEventListener(PAGE_BRIDGE_RESPONSE_EVENT, handleResponse as EventListener);
      resolve(detail as T);
    };

    window.addEventListener(PAGE_BRIDGE_RESPONSE_EVENT, handleResponse as EventListener);
    window.dispatchEvent(new CustomEvent(PAGE_BRIDGE_REQUEST_EVENT, {
      detail: JSON.stringify({
        requestId,
        type,
        ...payload,
      }),
    }));
  });
}

function handleGlobalYtrScrollTrap(event: WheelEvent | TouchEvent): void {
  const overlayOpen = overlayScrollTrapActive && !!document.querySelector('.ytr-image-overlay-shell');
  const menuOpen = menuScrollTrapActive && !!document.querySelector('.ytr-download-menu-open');

  if (!overlayOpen && !menuOpen) {
    if (overlayScrollTrapActive || menuScrollTrapActive) {
      overlayScrollTrapActive = false;
      menuScrollTrapActive = false;
      syncGlobalScrollTrap();
    }
    return;
  }

  if (overlayOpen) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }

  if (!menuOpen) return;
  const target = event.target;
  if (target instanceof Element && target.closest('.ytr-download-menu-open')) {
    return;
  }
  event.preventDefault();
  event.stopPropagation();
}

function syncGlobalScrollTrap(): void {
  const shouldInstall = (overlayScrollTrapActive && !!document.querySelector('.ytr-image-overlay-shell'))
    || (menuScrollTrapActive && !!document.querySelector('.ytr-download-menu-open'));
  if (shouldInstall === globalScrollTrapInstalled) return;

  if (shouldInstall) {
    document.addEventListener('wheel', handleGlobalYtrScrollTrap, { capture: true, passive: false });
    document.addEventListener('touchmove', handleGlobalYtrScrollTrap, { capture: true, passive: false });
  } else {
    document.removeEventListener('wheel', handleGlobalYtrScrollTrap, true);
    document.removeEventListener('touchmove', handleGlobalYtrScrollTrap, true);
  }

  globalScrollTrapInstalled = shouldInstall;
}

function setOverlayScrollTrap(active: boolean): void {
  overlayScrollTrapActive = active;
  syncGlobalScrollTrap();
}

function setMenuScrollTrap(active: boolean): void {
  menuScrollTrapActive = active;
  syncGlobalScrollTrap();
}

export default defineContentScript({
  matches: ['*://*.youtube.com/*'],
  runAt: 'document_start',
  cssInjectionMode: 'manifest',

  async main() {
    const settings = await loadSettings();
    currentSettings = settings;
    ensureYoutubeThemeObserver();
    applySettings(settings);
    syncPageContextFlags();
    setupPlaybackSpeed(settings);
    if (needsWatchPageEnhancements(settings)) {
      setupAutoSkipAds(settings);
      setupDefaultQuality(settings);
      setupDownloadThumbnailButton(settings);
      setupAiVideoChatButton(settings);
    }
    if (needsChannelPageEnhancements(settings)) {
      setupChannelPageEnhancements(settings);
    }
    if (needsFullscreenTracking(settings)) {
      setupFullscreenDetection();
    }
    queueInitialEnhancements(settings);
    document.addEventListener('yt-navigate-finish', () => {
      closeAllYtrMenus();
      setOverlayScrollTrap(false);
      setMenuScrollTrap(false);
      syncPageContextFlags();
      if (currentSettings) {
        setupPlaybackSpeed(currentSettings);
      }
      if (currentSettings && needsWatchPageEnhancements(currentSettings)) {
        setupAutoSkipAds(currentSettings);
        setupDefaultQuality(currentSettings);
        setupDownloadThumbnailButton(currentSettings);
        setupAiVideoChatButton(currentSettings);
      }
      if (currentSettings && needsChannelPageEnhancements(currentSettings)) {
        setupChannelPageEnhancements(currentSettings);
      }
      if (hasResolvedCustomLogo(currentSettings)) {
        scheduleCustomLogoSync([240, 960]);
      }
      if (currentSettings?.logoVariant === 'rewind') {
        window.setTimeout(() => syncRewindLogoTheme(), 240);
        window.setTimeout(() => syncRewindLogoTheme(), 960);
      }
      if (currentSettings?.logoVariant === 'youtube') {
        scheduleYouTubeLogoMetricSync([240, 960]);
      }
      scheduleFeedRevealSync([180, 560]);
    });

    browser.storage.onChanged.addListener((changes) => {
      if (changes.ytr_settings?.newValue) {
        const previousLocale = getContentLocale(currentSettings);
        const s = changes.ytr_settings.newValue as Settings;
        const nextLocale = getContentLocale(s);
        if (nextLocale !== previousLocale) {
          window.location.reload();
          return;
        }
        currentSettings = s;
        applySettings(s);
        syncPageContextFlags();
        if (getActiveScanFlags()) {
          startObserver();
          refreshObservedScanRoots();
        } else {
          refreshObservedScanRoots();
        }
        scheduleCustomLogoSync();
        scheduleYouTubeLogoMetricSync();
        scheduleFeedRevealSync();
        tagExploreSections();
        tagSidebarSections();
        tagActionButtons();
        tagFeedItems();
        setupPlaybackSpeed(s);
        setupAutoSkipAds(s);
        setupDefaultQuality(s);
        setupWatchTimer(s);
        setupDownloadThumbnailButton(s);
        setupAiVideoChatButton(s);
        setupChannelPageEnhancements(s);
        setupFullscreenDetection();
      }
    });
  },
});

function getContentLocale(settings: Settings | null = currentSettings): ContentLocale {
  const rawLocale = (settings?.language === 'auto'
    ? browser.i18n.getUILanguage()
    : settings?.language || 'en'
  ).toLowerCase();
  return rawLocale.startsWith('ru') ? 'ru' : 'en';
}

function scheduleLowPriorityTask(task: () => void, timeout = 1200, fallbackDelay = 120): number {
  const idleWindow = window as IdleWindow;
  if (typeof idleWindow.requestIdleCallback === 'function') {
    return idleWindow.requestIdleCallback(task, { timeout });
  }

  return window.setTimeout(task, fallbackDelay);
}

function logExtensionEvent(
  area: string,
  message: string,
  data?: unknown,
  level: ExtensionLogLevel = 'info',
): void {
  void browser.runtime.sendMessage({
    type: 'ytr_extension_log',
    level,
    area,
    message,
    data,
  }).catch(() => {});
}

function needsWatchPageEnhancements(settings: Settings): boolean {
  return settings.playbackSpeed > 0
    || settings.autoSkipAds
    || getEffectiveDefaultQuality(settings) !== 'auto'
    || settings.downloadThumbnailButton
    || settings.betaVideoFrameScreenshot
    || isAiVideoChatEnabled(settings);
}

function needsChannelPageEnhancements(settings: Settings): boolean {
  return settings.downloadChannelAssets || settings.showChannelStatsLinks;
}

function needsFullscreenTracking(settings: Settings): boolean {
  return settings.watchTimerEnabled || settings.watchTimeLimitMinutes > 0;
}

function isAiVideoChatEnabled(settings: Settings | null): boolean {
  return !!settings?.aiVideoChatEnabled;
}

function getEffectiveAiChatModel(settings: Settings | null): string {
  if (!settings) return '';
  if (settings.aiVideoChatModel === 'custom') {
    return settings.aiVideoChatCustomModel.trim();
  }
  return settings.aiVideoChatModel.trim();
}

function getEffectiveAiChatProvider(settings: Settings | null): AiChatProvider {
  const value = settings?.aiVideoChatProvider || 'openrouter';
  return ['openrouter', 'openai', 'anthropic', 'perplexity'].includes(value) ? value as AiChatProvider : 'openrouter';
}

function getEffectiveAiChatApiKey(settings: Settings | null): string {
  if (!settings) return '';
  const provider = getEffectiveAiChatProvider(settings);
  if (provider === 'openai') return settings.aiVideoChatOpenAiApiKey.trim();
  if (provider === 'anthropic') return settings.aiVideoChatAnthropicApiKey.trim();
  if (provider === 'perplexity') return settings.aiVideoChatPerplexityApiKey.trim();
  return (settings.aiVideoChatOpenRouterApiKey || settings.aiVideoChatApiKey).trim();
}

function getEffectiveAiChatEndpoint(settings: Settings | null): string {
  return '';
}

function getEffectiveAiTemperature(settings: Settings | null): number {
  const value = Number(settings?.aiVideoChatTemperature);
  if (!Number.isFinite(value)) return 0.2;
  return Math.min(2, Math.max(0, Math.round(value * 100) / 100));
}

function ensureMaterialSymbolsFont(): void {
  if (document.getElementById('ytr-material-symbols-rounded')) return;
  const link = document.createElement('link');
  link.id = 'ytr-material-symbols-rounded';
  link.rel = 'stylesheet';
  link.href = 'https://fonts.googleapis.com/css2?family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,100..700,0..1,-50..200&icon_names=content_copy,developer_guide,refresh,send,settings,thumb_down,thumb_up';
  document.head.appendChild(link);
}

function getResolvedLogoKind(settings: Settings | null): ManagedLogoKind | null {
  if (!settings) return null;
  if (settings.logoVariant === 'rewind') return 'rewind';
  if (settings.logoVariant === 'custom' && settings.customLogo) return 'custom';
  return null;
}

function getResolvedLogoSource(settings: Settings | null): string | null {
  if (!settings) return null;
  if (settings.logoVariant === 'rewind') return BUILTIN_REWIND_LOGO_URL;
  if (settings.logoVariant === 'custom' && settings.customLogo) return settings.customLogo;
  return null;
}

function getResolvedLogoRatio(settings: Settings | null): number | 'auto' {
  if (!settings) return 'auto';
  if (settings.logoVariant === 'rewind') {
    return BUILTIN_REWIND_LOGO_RATIO;
  }
  if (settings.logoVariant === 'custom') {
    return settings.customLogoRatio || 'auto';
  }
  return 'auto';
}

function hasResolvedCustomLogo(settings: Settings | null): boolean {
  return !!getResolvedLogoKind(settings);
}

function getLogoScale(settings: Settings | null, variant = settings?.logoVariant || 'youtube'): number {
  if (!settings) {
    if (variant === 'rewind') return DEFAULT_SETTINGS.rewindLogoScale;
    if (variant === 'custom') return DEFAULT_SETTINGS.customLogoScale;
    return DEFAULT_SETTINGS.youtubeLogoScale;
  }

  if (variant === 'rewind') return settings.rewindLogoScale || DEFAULT_SETTINGS.rewindLogoScale;
  if (variant === 'custom') return settings.customLogoScale || DEFAULT_SETTINGS.customLogoScale;
  return settings.youtubeLogoScale || DEFAULT_SETTINGS.youtubeLogoScale;
}

function queueInitialEnhancements(settings: Settings): void {
  if (hasResolvedCustomLogo(settings)) {
    scheduleLowPriorityTask(() => scheduleCustomLogoSync(), 900, 80);
  }
  if (settings.logoVariant === 'rewind') {
    scheduleLowPriorityTask(() => syncRewindLogoTheme(settings), 900, 80);
  }
  if (settings.logoVariant === 'youtube') {
    scheduleLowPriorityTask(() => scheduleYouTubeLogoMetricSync([0, 240, 960]), 900, 80);
  }

  if (getActiveScanFlags()) {
    scheduleLowPriorityTask(() => startObserver(), 1200, 160);
  }

  if (needsWatchPageEnhancements(settings)) {
    scheduleLowPriorityTask(() => {
      setupPlaybackSpeed(settings);
      setupAutoSkipAds(settings);
      setupDefaultQuality(settings);
      setupDownloadThumbnailButton(settings);
      setupAiVideoChatButton(settings);
    }, 1400, 220);
  }

  if (needsChannelPageEnhancements(settings)) {
    scheduleLowPriorityTask(() => {
      setupChannelPageEnhancements(settings);
    }, 1500, 260);
  }

  if (settings.watchTimerEnabled || settings.watchTimeLimitMinutes > 0) {
    scheduleLowPriorityTask(() => setupWatchTimer(settings), 1600, 280);
  }

  if (needsFullscreenTracking(settings)) {
    scheduleLowPriorityTask(() => setupFullscreenDetection(), 1800, 360);
  }
}

function injectDefaultQualityBridge(): void {
  if (qualityBridgeInjected) return;
  qualityBridgeInjected = true;

  const scriptId = 'ytr-default-quality-bridge';
  if (document.getElementById(scriptId)) return;

  const script = document.createElement('script');
  script.id = scriptId;
  const bridgePath = 'default-quality-bridge.js' as Parameters<typeof browser.runtime.getURL>[0];
  script.src = browser.runtime.getURL(bridgePath);
  script.async = false;
  script.onload = () => {
    dispatchDefaultQualityBridge(getEffectiveDefaultQuality(currentSettings));
    script.remove();
  };
  (document.head || document.documentElement).appendChild(script);
}

function dispatchDefaultQualityBridge(quality: string): void {
  const targets: Array<Window | Document | HTMLElement | null> = [
    window,
    document,
    document.documentElement,
  ];

  for (const target of targets) {
    target?.dispatchEvent(new CustomEvent('ytr:set-default-quality', {
      detail: { quality },
    }));
  }
}

function getEffectiveDefaultQuality(settings: Settings | null): string {
  if (!settings?.betaEnabled) return 'auto';
  return settings.defaultQuality || 'auto';
}

function isObserverIgnoredNode(node: Node | null): boolean {
  if (!(node instanceof Element)) return false;
  return !!node.closest(OBSERVER_IGNORED_REGION_SELECTOR);
}

function getMainVideoElement(): HTMLVideoElement | null {
  const selectors = [
    '#movie_player video.html5-main-video',
    '#movie_player .html5-video-player video',
    'ytd-player #movie_player video',
    '#player video.html5-main-video',
    '#player video',
  ];

  for (const selector of selectors) {
    const video = document.querySelector(selector);
    if (video instanceof HTMLVideoElement) return video;
  }

  const candidates = [...document.querySelectorAll('video')].filter((video): video is HTMLVideoElement => video instanceof HTMLVideoElement);
  return candidates.find((video) => video.classList.contains('html5-main-video'))
    ?? candidates.find((video) => !!video.closest('#movie_player, ytd-player, #player'))
    ?? null;
}

function setElementFlag(element: Element, name: string, enabled: boolean): void {
  if (enabled) {
    element.setAttribute(name, 'true');
    return;
  }

  element.removeAttribute(name);
}

function syncPageContextFlags(): void {
  document.documentElement.dataset.ytrHomePage = String(!!document.querySelector('ytd-browse[page-subtype="home"]'));
}

function needsExploreTags(): boolean {
  const d = document.documentElement.dataset;
  return d.ytrHideShorts === 'true'
    || d.ytrHidePosts === 'true'
    || d.ytrHideBreakingNews === 'true'
    || d.ytrHideLatestPosts === 'true'
    || d.ytrHideExploreTopics === 'true'
    || d.ytrHidePlayables === 'true';
}

function needsSidebarTags(): boolean {
  const d = document.documentElement.dataset;
  return d.ytrHideShorts === 'true'
    || d.ytrHideSidebarSubscriptions === 'true'
    || d.ytrHideSidebarYou === 'true'
    || d.ytrHideSidebarExplore === 'true'
    || d.ytrHideSidebarMoreFromYt === 'true'
    || d.ytrHideSidebarReportHistory === 'true';
}

function needsFeedTags(): boolean {
  const d = document.documentElement.dataset;
  return d.ytrHideMixes === 'true'
    || d.ytrBetaFeedMotion === 'true'
    || d.ytrDisableAvatarLive === 'true'
    || d.ytrHideSearchShorts === 'true'
    || d.ytrHideSearchPeopleWatched === 'true'
    || d.ytrHideNewBadge === 'true';
}

function needsActionTags(): boolean {
  const d = document.documentElement.dataset;
  return d.ytrHideShareButton === 'true'
    || d.ytrHideDownloadButton === 'true'
    || d.ytrHideClipButton === 'true'
    || d.ytrHideThanksButton === 'true'
    || d.ytrHideSaveButton === 'true'
    || d.ytrHideAskButton === 'true';
}

function applySettings(s: Settings): void {
  const el = document.documentElement;
  const d = el.dataset;
  applyContentInterfaceThemeTokens(s);

  d.ytrNoAdaptiveDesc = String(s.adaptiveColorsDescription);
  d.ytrStableDescriptionColors = String(!!(s.betaEnabled && s.betaStableDescriptionColors));

  // Top bar
  d.ytrHideTopbarCreate = String(s.hideTopbarCreate);
  d.ytrHideTopbarVoiceSearch = String(s.hideTopbarVoiceSearch);
  d.ytrHideTopbarNotifications = String(s.hideTopbarNotifications);
  d.ytrHideCountryCode = String(s.hideCountryCode);
  d.ytrHideTopbarSearch = String(s.hideTopbarSearch);

  // Thumbnail effect
  d.ytrThumbnailEffect = s.thumbnailEffect || 'none';
  d.ytrThumbnailNoReveal = String(!s.thumbnailHoverReveal);
  d.ytrDisableThumbnailPreview = String(s.disableThumbnailPreview);

  // Inject pixel filter SVG only when needed
  if (s.thumbnailEffect === 'pixelate') injectPixelFilter();

  if (s.videosPerRow > 0) {
    d.ytrVideosPerRow = String(s.videosPerRow);
    d.ytrHomeResponsiveGrid = String(!!s.homepageResponsiveGrid);
    el.style.setProperty('--ytr-videos-per-row', String(s.videosPerRow));
    syncResponsiveHomeGridColumns(s);
    scheduleLowPriorityTask(() => setupPrefetch(), 1400, 260);
  } else {
    delete d.ytrVideosPerRow;
    delete d.ytrHomeResponsiveGrid;
    el.style.removeProperty('--ytr-videos-per-row');
    el.style.removeProperty('--ytr-responsive-videos-per-row');
    teardownResponsiveHomeGrid();
    teardownPrefetch();
  }

  d.ytrHideShorts = String(s.hideShorts);
  d.ytrHidePosts = String(s.hidePosts);
  d.ytrHideMixes = String(s.hideMixes);
  d.ytrHideBreakingNews = String(s.hideBreakingNews);
  d.ytrHideLatestPosts = String(s.hideLatestPosts);
  d.ytrHideExploreTopics = String(s.hideExploreTopics);

  d.ytrHideSearchShorts = String(s.hideSearchShorts);
  d.ytrHideSearchChannels = String(s.hideSearchChannels);
  d.ytrHideSearchPeopleWatched = String(s.hideSearchPeopleWatched);

  d.ytrHideSidebarSubscriptions = String(s.hideSidebarSubscriptions);
  d.ytrHideSidebarYou = String(s.hideSidebarYou);
  d.ytrHideSidebarExplore = String(s.hideSidebarExplore);
  d.ytrHideSidebarMoreFromYt = String(s.hideSidebarMoreFromYT);
  d.ytrHideSidebarReportHistory = String(s.hideSidebarReportHistory);
  d.ytrHideSidebarFooter = String(s.hideSidebarFooter);

  d.ytrAvatarShape = s.avatarShape;
  d.ytrThumbnailShape = s.thumbnailShape || 'none';
  d.ytrDisableHoverAnimation = String(s.disableHoverAnimation);
  d.ytrBannerStyle = s.bannerStyle || 'none';
  d.ytrClassicLikeIcons = String(s.classicLikeIcons);
  syncClassicLikeIconsState(!!s.classicLikeIcons);
  d.ytrClassicPlayer = String(s.classicPlayer);
  d.ytrWidePlayer = String(s.widePlayer);
  d.ytrHideNewBadge = String(s.hideNewBadge);

  // Video buttons
  d.ytrHideJoinButton = String(s.hideJoinButton);
  d.ytrHideSubscribeButton = String(s.hideSubscribeButton);
  d.ytrHideLikeDislike = String(s.hideLikeDislike);
  d.ytrHideShareButton = String(s.hideShareButton);
  d.ytrHideDownloadButton = String(s.hideDownloadButton);
  d.ytrHideClipButton = String(s.hideClipButton);
  d.ytrHideThanksButton = String(s.hideThanksButton);
  d.ytrHideSaveButton = String(s.hideSaveButton);
  d.ytrHideAskButton = String(s.hideAskButton);

  // Logo presentation
  const resolvedLogoKind = getResolvedLogoKind(s);
  const resolvedLogoSource = getResolvedLogoSource(s);
  const resolvedLogoRatio = getResolvedLogoRatio(s);
  d.ytrLogoVariant = s.logoVariant;
  el.style.setProperty('--ytr-youtube-logo-scale', String(getLogoScale(s, 'youtube') / 100));
  el.style.setProperty('--ytr-rewind-logo-scale', String(getLogoScale(s, 'rewind') / 100));
  el.style.setProperty('--ytr-custom-logo-scale', String(getLogoScale(s, 'custom') / 100));
  el.style.setProperty('--ytr-rewind-logo-ratio', String(BUILTIN_REWIND_LOGO_RATIO));
  el.style.setProperty('--ytr-rewind-logo-mask', `url("${BUILTIN_REWIND_LOGO_URL}")`);
  el.style.setProperty('--ytr-rewind-logo-color', getRewindLogoColor(s, getYoutubeThemeMode()));
  if (resolvedLogoKind) {
    d.ytrCustomLogo = 'true';
    d.ytrCustomLogoKind = resolvedLogoKind;
    el.style.setProperty('--ytr-custom-logo-ratio', String(resolvedLogoRatio));
    if (resolvedLogoKind === 'custom' && resolvedLogoSource) {
      el.style.setProperty('--ytr-custom-logo', `url("${resolvedLogoSource}")`);
    } else {
      el.style.removeProperty('--ytr-custom-logo');
    }
  } else {
    delete d.ytrCustomLogo;
    delete d.ytrCustomLogoKind;
    el.style.removeProperty('--ytr-custom-logo');
    el.style.removeProperty('--ytr-custom-logo-ratio');
    delete d.ytrCustomLogoState;
  }
  d.ytrHideLogoAnimation = String(s.hideLogoAnimation);
  syncCustomLogoElement(s);
  if (s.logoVariant === 'youtube') {
    scheduleYouTubeLogoMetricSync([0, 180, 720]);
  }

  // Playables
  d.ytrHidePlayables = String(s.hidePlayables);
  d.ytrHideFilterBar = String(s.hideFilterBar);
  d.ytrDisableAvatarLive = String(!!(s.betaEnabled && s.disableAvatarLiveRedirect));
  d.ytrBetaFeedMotion = 'false';

  updateThumbnailPreviewSuppression();
}

const THUMBNAIL_CARD_SELECTOR = [
  'ytd-rich-item-renderer',
  'ytd-compact-video-renderer',
  'ytd-video-renderer',
  'ytd-grid-video-renderer',
  'yt-lockup-view-model',
  'ytd-rich-grid-media',
].join(', ');

const THUMBNAIL_MEDIA_SELECTOR = [
  'ytd-thumbnail img',
  'ytd-thumbnail source',
  'ytd-playlist-thumbnail img',
  'ytd-playlist-thumbnail source',
  'yt-thumbnail-view-model img',
  'yt-thumbnail-view-model source',
  '.yt-lockup-view-model-wiz__content-image img',
  '.yt-lockup-view-model-wiz__content-image source',
  'ytd-moving-thumbnail-renderer img',
  'ytd-moving-thumbnail-renderer source',
  'ytd-moving-thumbnail-renderer video',
  'ytd-video-preview img',
  'ytd-video-preview source',
  'ytd-video-preview video',
].join(', ');

function shouldSuppressThumbnailPreview(settings: Settings | null = currentSettings): boolean {
  if (!settings) return false;
  return document.documentElement.dataset.ytrHomePage === 'true'
    || !!settings.disableThumbnailPreview
    || (settings.thumbnailEffect || 'none') !== 'none';
}

function isAnimatedThumbnailUrl(value: string | null | undefined): boolean {
  return /\/an_webp\//i.test(value || '');
}

function extractVideoIdFromUrl(value: string | null | undefined): string | null {
  if (!value) return null;
  const animatedMatch = value.match(/\/an_webp\/([^/?]+)/i);
  if (animatedMatch?.[1]) return animatedMatch[1];

  try {
    const parsed = new URL(value, window.location.origin);
    const v = parsed.searchParams.get('v');
    if (v) return v;
    const shortsMatch = parsed.pathname.match(/\/shorts\/([^/?]+)/i);
    if (shortsMatch?.[1]) return shortsMatch[1];
  } catch {
    const watchMatch = value.match(/[?&]v=([^&]+)/i);
    if (watchMatch?.[1]) return watchMatch[1];
    const shortsMatch = value.match(/\/shorts\/([^/?]+)/i);
    if (shortsMatch?.[1]) return shortsMatch[1];
  }

  return null;
}

function getThumbnailVideoId(target: Element): string | null {
  const card = target.closest(THUMBNAIL_CARD_SELECTOR) || target.closest('a, ytd-thumbnail, yt-thumbnail-view-model');
  const links = card?.querySelectorAll?.('a[href]') || [];
  for (const link of links) {
    const href = (link as HTMLAnchorElement).href || (link as HTMLAnchorElement).getAttribute('href');
    const id = extractVideoIdFromUrl(href);
    if (id) return id;
  }
  return extractVideoIdFromUrl((target as HTMLImageElement).currentSrc || (target as HTMLImageElement).getAttribute?.('src'));
}

function buildStaticThumbnailUrl(videoId: string): string {
  return `https://i.ytimg.com/vi/${videoId}/hqdefault.jpg`;
}

function rememberStaticThumbnailSource(target: Element): void {
  if (!(target instanceof HTMLImageElement || target instanceof HTMLSourceElement || target instanceof HTMLVideoElement)) return;
  const currentSrc = target instanceof HTMLImageElement || target instanceof HTMLVideoElement
    ? (target.currentSrc || target.src || target.getAttribute('src') || '')
    : (target.srcset || target.getAttribute('srcset') || '');
  if (!currentSrc || isAnimatedThumbnailUrl(currentSrc)) return;
  target.dataset.ytrStaticSrc = currentSrc;
  if (target instanceof HTMLSourceElement && target.srcset) {
    target.dataset.ytrStaticSrcset = target.srcset;
  }
  if (target instanceof HTMLImageElement && target.srcset && !isAnimatedThumbnailUrl(target.srcset)) {
    target.dataset.ytrStaticSrcset = target.srcset;
  }
}

function restoreStaticThumbnailSource(target: Element): void {
  if (!(target instanceof HTMLImageElement || target instanceof HTMLSourceElement || target instanceof HTMLVideoElement)) return;

  const currentValue = target instanceof HTMLSourceElement
    ? (target.srcset || target.getAttribute('srcset') || '')
    : (target.currentSrc || target.src || target.getAttribute('src') || '');

  if (!currentValue) return;
  if (!isAnimatedThumbnailUrl(currentValue)) {
    rememberStaticThumbnailSource(target);
    return;
  }

  const videoId = getThumbnailVideoId(target);
  const fallbackStatic = target.dataset.ytrStaticSrc || (videoId ? buildStaticThumbnailUrl(videoId) : '');

  if (target instanceof HTMLSourceElement) {
    const nextSrcset = target.dataset.ytrStaticSrcset || fallbackStatic;
    if (nextSrcset) target.srcset = nextSrcset;
    return;
  }

  if (target instanceof HTMLVideoElement) {
    target.pause();
    target.removeAttribute('src');
    target.load();
    return;
  }

  if (target.dataset.ytrStaticSrcset) {
    target.srcset = target.dataset.ytrStaticSrcset;
  } else {
    target.removeAttribute('srcset');
  }

  if (fallbackStatic) {
    target.src = fallbackStatic;
  }
}

function syncThumbnailPreviewSuppressionForRoot(root: ParentNode): void {
  root.querySelectorAll?.(THUMBNAIL_MEDIA_SELECTOR).forEach((node) => {
    restoreStaticThumbnailSource(node);
  });
}

function flushThumbnailPreviewSuppression(): void {
  thumbnailPreviewSuppressionRaf = 0;
  const roots = [...thumbnailPreviewSuppressionRoots];
  thumbnailPreviewSuppressionRoots.clear();
  roots.forEach((root) => syncThumbnailPreviewSuppressionForRoot(root));
}

function scheduleThumbnailPreviewSuppression(root: Element | ParentNode | null): void {
  if (!shouldSuppressThumbnailPreview()) return;
  thumbnailPreviewSuppressionRoots.add(root || document);
  if (thumbnailPreviewSuppressionRaf) return;
  thumbnailPreviewSuppressionRaf = requestAnimationFrame(flushThumbnailPreviewSuppression);
}

function updateThumbnailPreviewSuppression(): void {
  thumbnailPreviewSuppressionObserver?.disconnect();
  thumbnailPreviewSuppressionObserver = null;
  if (!shouldSuppressThumbnailPreview()) return;

  scheduleThumbnailPreviewSuppression(document);
  thumbnailPreviewSuppressionObserver = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      if (mutation.type === 'attributes') {
        const target = mutation.target as Element;
        if (target.matches(THUMBNAIL_MEDIA_SELECTOR)) {
          scheduleThumbnailPreviewSuppression(target.closest(THUMBNAIL_CARD_SELECTOR) || target.parentElement || document.documentElement);
        }
        continue;
      }
      mutation.addedNodes.forEach((node) => {
        if (!(node instanceof Element)) return;
        if (node.matches(THUMBNAIL_MEDIA_SELECTOR)) {
          scheduleThumbnailPreviewSuppression(node.closest(THUMBNAIL_CARD_SELECTOR) || node.parentElement || document.documentElement);
          return;
        }
        if (node.querySelector?.(THUMBNAIL_MEDIA_SELECTOR)) {
          scheduleThumbnailPreviewSuppression(node);
        }
      });
    }
  });

  thumbnailPreviewSuppressionObserver.observe(document.documentElement, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: ['src', 'srcset'],
  });
}

function isVideoLogo(src: string): boolean {
  return /^data:video\//i.test(src) || /\.(mp4|webm|ogg|mov)(?:$|[?#])/i.test(src);
}

function disconnectLogoStateObserver(): void {
  logoStateObserver?.disconnect();
  logoStateObserver = null;
  observedLogoRenderer = null;
}

function ensureYoutubeThemeObserver(): void {
  if (youtubeThemeObserver) return;

  youtubeThemeObserver = new MutationObserver(() => {
    if (youtubeThemeSyncRaf) return;
    youtubeThemeSyncRaf = requestAnimationFrame(() => {
      youtubeThemeSyncRaf = 0;
      syncRewindLogoTheme();
    });
  });

  youtubeThemeObserver.observe(document.documentElement, {
    subtree: true,
    attributes: true,
    attributeFilter: ['dark', 'class', 'style'],
  });
}

function hasActiveEventLogo(): boolean {
  const yoodle = document.querySelector('ytd-topbar-logo-renderer ytd-yoodle-renderer:not([hidden])') as HTMLElement | null;
  if (!yoodle) return false;

  const style = window.getComputedStyle(yoodle);
  if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') {
    return false;
  }

  const rect = yoodle.getBoundingClientRect();
  return rect.width > 0 && rect.height > 0;
}

function ensureLogoStateObserver(): void {
  const renderer = document.querySelector('ytd-topbar-logo-renderer') as HTMLElement | null;
  if (!renderer) {
    disconnectLogoStateObserver();
    return;
  }

  if (observedLogoRenderer === renderer && logoStateObserver) return;

  disconnectLogoStateObserver();
  observedLogoRenderer = renderer;
  logoStateObserver = new MutationObserver(() => {
    requestAnimationFrame(() => syncCustomLogoState());
  });
  logoStateObserver.observe(renderer, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ['hidden', 'style', 'class'],
  });
}

function syncCustomLogoState(settings: Settings | null = currentSettings): void {
  const root = document.documentElement;
  if (!hasResolvedCustomLogo(settings)) {
    delete root.dataset.ytrCustomLogoState;
    disconnectLogoStateObserver();
    return;
  }

  if (settings.hideLogoAnimation) {
    root.dataset.ytrCustomLogoState = 'custom';
    syncCustomLogoMediaPlayback('custom');
    disconnectLogoStateObserver();
    return;
  }

  ensureLogoStateObserver();
  const nextState = hasActiveEventLogo() ? 'event' : 'custom';
  root.dataset.ytrCustomLogoState = nextState;
  syncCustomLogoMediaPlayback(nextState);
}

function syncCustomLogoElement(settings: Settings | null = currentSettings): void {
  const logoLink = document.querySelector('ytd-topbar-logo-renderer a#logo') as HTMLAnchorElement | null;
  if (!logoLink) return;

  const existingSlot = logoLink.querySelector('.ytr-custom-logo-slot') as HTMLSpanElement | null;
  const resolvedLogoKind = getResolvedLogoKind(settings);
  const resolvedLogoSource = getResolvedLogoSource(settings);
  const resolvedLogoRatio = getResolvedLogoRatio(settings);

  if (!resolvedLogoKind) {
    existingSlot?.remove();
    syncCustomLogoState(settings);
    return;
  }

  if (existingSlot) {
    existingSlot.style.setProperty('--ytr-custom-logo-ratio', String(resolvedLogoRatio));
  }
  if (resolvedLogoKind === 'rewind' && existingSlot?.dataset.ytrLogoKind === 'rewind') {
    syncCustomLogoState(settings);
    return;
  }

  const currentMedia = existingSlot?.querySelector('.ytr-custom-logo-media') as (HTMLImageElement | HTMLVideoElement) | null;
  if (resolvedLogoKind === 'custom' && currentMedia?.dataset.src === resolvedLogoSource) {
    syncCustomLogoState(settings);
    return;
  }

  existingSlot?.remove();

  const slot = document.createElement('span');
  slot.className = 'ytr-custom-logo-slot';
  slot.dataset.ytrLogoKind = resolvedLogoKind;
  slot.style.setProperty('--ytr-custom-logo-ratio', String(resolvedLogoRatio));

  if (resolvedLogoKind === 'rewind') {
    const rewindLogo = document.createElement('span');
    rewindLogo.className = 'ytr-custom-logo-rewind';
    rewindLogo.setAttribute('aria-hidden', 'true');
    slot.appendChild(rewindLogo);
  } else if (resolvedLogoSource && isVideoLogo(resolvedLogoSource)) {
    const video = document.createElement('video');
    video.className = 'ytr-custom-logo-media';
    video.dataset.src = resolvedLogoSource;
    video.src = resolvedLogoSource;
    video.muted = true;
    video.defaultMuted = true;
    video.autoplay = true;
    video.loop = true;
    video.playsInline = true;
    video.setAttribute('aria-hidden', 'true');
    slot.appendChild(video);
    setTimeout(() => {
      void video.play().catch(() => {});
    }, 0);
  } else if (resolvedLogoSource) {
    const img = document.createElement('img');
    img.className = 'ytr-custom-logo-media';
    img.dataset.src = resolvedLogoSource;
    img.src = resolvedLogoSource;
    img.alt = '';
    img.setAttribute('aria-hidden', 'true');
    slot.appendChild(img);
  }

  logoLink.appendChild(slot);
  syncCustomLogoState(settings);
}

function syncCustomLogoMediaPlayback(state: 'custom' | 'event'): void {
  const media = document.querySelector('ytd-topbar-logo-renderer a#logo .ytr-custom-logo-media') as HTMLVideoElement | HTMLImageElement | null;
  if (!(media instanceof HTMLVideoElement)) return;

  if (state === 'event') {
    media.pause();
    return;
  }

  void media.play().catch(() => {});
}

function clearScheduledTimers(timers: number[]): void {
  timers.forEach((timer) => clearTimeout(timer));
}

function scheduleCustomLogoSync(delays: number | number[] = 0): void {
  clearScheduledTimers(customLogoSyncTimers);
  if (!hasResolvedCustomLogo(currentSettings)) {
    customLogoSyncTimers = [];
    syncCustomLogoElement();
    return;
  }
  const queue = Array.isArray(delays) ? delays : [delays];
  customLogoSyncTimers = queue.map((delay) => window.setTimeout(() => syncCustomLogoElement(), delay));
}

function syncYouTubeLogoMetrics(): void {
  if (currentSettings?.logoVariant !== 'youtube') return;

  const logoLink = document.querySelector('ytd-topbar-logo-renderer a#logo') as HTMLElement | null;
  const logoIcon = logoLink?.querySelector('yt-icon#logo-icon, #logo-icon') as HTMLElement | null;
  if (!logoLink || !logoIcon) return;

  const linkRect = logoLink.getBoundingClientRect();
  const iconRect = logoIcon.getBoundingClientRect();
  const rootStyle = document.documentElement.style;

  if (linkRect.width > 0) {
    rootStyle.setProperty('--ytr-youtube-logo-base-link-width', `${linkRect.width}px`);
  }
  if (iconRect.width > 0) {
    rootStyle.setProperty('--ytr-youtube-logo-base-width', `${iconRect.width}px`);
  }
  if (iconRect.height > 0) {
    rootStyle.setProperty('--ytr-youtube-logo-base-height', `${iconRect.height}px`);
  }
}

function scheduleYouTubeLogoMetricSync(delays: number | number[] = 0): void {
  clearScheduledTimers(youtubeLogoMetricSyncTimers);
  if (currentSettings?.logoVariant !== 'youtube') {
    youtubeLogoMetricSyncTimers = [];
    return;
  }

  const queue = Array.isArray(delays) ? delays : [delays];
  youtubeLogoMetricSyncTimers = queue.map((delay) => window.setTimeout(syncYouTubeLogoMetrics, delay));
}

function syncRewindLogoTheme(settings: Settings | null = currentSettings): void {
  if (!settings) return;
  applyContentInterfaceThemeTokens(settings);
  document.documentElement.style.setProperty('--ytr-rewind-logo-color', getRewindLogoColor(settings, getYoutubeThemeMode()));
}

function scheduleFeedRevealSync(delays: number | number[] = 0): void {
  clearScheduledTimers(feedRevealSyncTimers);
  if (document.documentElement.dataset.ytrBetaFeedMotion !== 'true') {
    feedRevealSyncTimers = [];
    syncFeedRevealObserver();
    return;
  }
  const queue = Array.isArray(delays) ? delays : [delays];
  feedRevealSyncTimers = queue.map((delay) => window.setTimeout(syncFeedRevealObserver, delay));
}

// --- Explore More Topics: tag sections by title text ---

const EXPLORE_KEYWORDS = [
  'explore more topics',
  'другие темы',
  'ещё больше тем',
  'обзор тем',
  'больше тем',
];

const PLAYABLES_KEYWORDS = [
  'playables',
  'игры',
];

function tagExploreSections(): void {
  if (!needsExploreTags()) return;
  document.querySelectorAll('ytd-rich-section-renderer').forEach((section) => {
    const text = (section.textContent || '').toLowerCase();
    setElementFlag(section, 'data-ytr-shorts-section', !!section.querySelector('ytd-rich-shelf-renderer[is-shorts], a[href^="/shorts"]'));
    setElementFlag(section, 'data-ytr-posts-section', !!section.querySelector('ytd-post-renderer'));
    setElementFlag(section, 'data-ytr-breaking-news-section', !!section.querySelector('ytd-breaking-news-section-renderer'));
    setElementFlag(section, 'data-ytr-latest-posts-section', !!section.querySelector('ytd-rich-shelf-renderer:not([is-shorts]) ytd-post-renderer'));
    setElementFlag(section, 'data-ytr-explore-topics',
      EXPLORE_KEYWORDS.some((kw) => text.includes(kw)) ||
      !!section.querySelector('ytd-feed-nudge-renderer, yt-chip-cloud-renderer, iron-selector#chips, yt-related-chip-cloud-renderer'));
    setElementFlag(section, 'data-ytr-playables',
      PLAYABLES_KEYWORDS.some((kw) => text.includes(kw)) ||
      !!section.querySelector('ytd-rich-shelf-renderer[is-playables], [aria-label*="Playables"], [aria-label*="playables"], a[href*="/playables"]'));
  });
}

// --- Sidebar: tag sections by content ---

function tagSidebarSections(): void {
  if (!needsSidebarTags()) return;
  document.querySelectorAll('ytd-guide-section-renderer').forEach((section) => {
    const isSubscriptions = !!section.querySelector('ytd-guide-collapsible-section-entry-renderer');
    const isYou = !!section.querySelector('a[href="/feed/history"], a[href="/feed/library"], a[href*="list=WL"], a[href*="list=LL"]');
    const isMoreYt = !!section.querySelector('a[href*="youtube.com/premium"], a[href*="/premium"], a[href*="music.youtube.com"], a[href*="/kids"]');
    const title = section.querySelector('#guide-section-title');
    const isExplore = !!title?.textContent?.trim() && !isSubscriptions && !isYou && !isMoreYt;

    setElementFlag(section, 'data-ytr-sidebar-subscriptions', isSubscriptions);
    setElementFlag(section, 'data-ytr-sidebar-you', isYou);
    setElementFlag(section, 'data-ytr-sidebar-more-yt', isMoreYt);
    setElementFlag(section, 'data-ytr-sidebar-explore', isExplore);
  });

  document.querySelectorAll('ytd-guide-entry-renderer, ytd-mini-guide-entry-renderer').forEach((entry) => {
    const link = entry.querySelector('a');
    const title = (link?.getAttribute('title') || link?.textContent || '').trim().toLowerCase();
    const href = link?.getAttribute('href') || '';
    setElementFlag(entry, 'data-ytr-shorts-entry', href === '/shorts' || title === 'shorts');
    setElementFlag(entry, 'data-ytr-report-history-entry', href === '/reporthistory');
  });
}

// --- Action buttons: tag by aria-label ---

const ACTION_BUTTON_KEYWORDS: Record<string, string[]> = {
  ask: ['ask', 'спросить'],
  share: ['share', 'поделиться', 'compartir', 'compartilhar', 'partager', 'teilen', 'paylaş', '共有', '공유', '分享'],
  download: ['download', 'скачать', 'descargar', 'baixar', 'télécharger', 'herunterladen', 'indir', 'ダウンロード', '다운로드', '下载', 'offline'],
  clip: ['clip', 'клип', 'recortar', 'recorte', 'extrait', 'schneiden', 'klip', 'クリップ', '클립', '剪辑', 'remix', 'ремикс'],
  thanks: ['thanks', 'спасибо', 'gracias', 'obrigado', 'merci', 'danke', 'teşekkür', 'ありがとう', '감사', '感谢', 'super thanks'],
  save: ['save', 'сохранить', 'guardar', 'salvar', 'enregistrer', 'speichern', 'kaydet', '保存', '저장', 'зберегти', 'playlist'],
};

function tagActionButtons(): void {
  if (!needsActionTags()) return;
  const containers = document.querySelectorAll('#top-level-buttons-computed, #flexible-item-buttons, ytd-menu-renderer.ytd-watch-metadata');
  containers.forEach((container) => {
    container.querySelectorAll('yt-button-view-model:not([data-ytr-action]), button-view-model:not([data-ytr-action]), ytd-button-renderer:not([data-ytr-action]), ytd-download-button-renderer:not([data-ytr-action])').forEach((btn) => {
      const label = (btn.getAttribute('aria-label') || btn.querySelector('button')?.getAttribute('aria-label') || btn.textContent || '').toLowerCase();
      for (const [action, keywords] of Object.entries(ACTION_BUTTON_KEYWORDS)) {
        if (keywords.some((kw) => label.includes(kw))) {
          btn.setAttribute('data-ytr-action', action);
          return;
        }
      }
    });
  });
}

// --- Feed items: tag live, upcoming, mixes, podcasts, songs ---

const UPCOMING_KEYWORDS = ['scheduled for', 'notify me', 'напомнить', 'запланирован на'];
const PODCAST_KEYWORDS = ['episodes', 'episode', 'view full podcast', 'эпизодов', 'эпизод', 'подкаст', 'episodios', 'episódios', 'épisodes', 'episoden', 'bölüm', 'エピソード', '에피소드', '集'];

// Only scan untagged items (skip already-processed ones)
const FEED_ITEM_SELECTOR = 'ytd-rich-item-renderer:not([data-ytr-scanned]), ytd-video-renderer:not([data-ytr-scanned]), ytd-compact-video-renderer:not([data-ytr-scanned]), ytd-grid-video-renderer:not([data-ytr-scanned])';
const FEED_REVEAL_SELECTOR = 'ytd-browse[page-subtype="home"] ytd-rich-item-renderer, ytd-browse[page-subtype="home"] ytd-video-renderer, ytd-browse[page-subtype="home"] ytd-compact-video-renderer, ytd-browse[page-subtype="home"] ytd-grid-video-renderer';

function ensureFeedRevealObserver(): IntersectionObserver {
  if (feedRevealObserver) return feedRevealObserver;

  feedRevealObserver = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      const item = entry.target as HTMLElement;
      if (entry.isIntersecting) {
        if (item.getAttribute('data-ytr-feed-reveal') === 'visible') {
          feedRevealObserver?.unobserve(item);
          return;
        }
        item.setAttribute('data-ytr-feed-reveal', 'pending');
        requestAnimationFrame(() => {
          item.setAttribute('data-ytr-feed-reveal', 'visible');
          feedRevealObserver?.unobserve(item);
        });
      }
    });
  }, {
    threshold: 0.04,
    rootMargin: '10% 0px 10% 0px',
  });

  return feedRevealObserver;
}

function syncFeedRevealObserver(): void {
  const items = document.querySelectorAll(FEED_REVEAL_SELECTOR);
  const enabled = document.documentElement.dataset.ytrBetaFeedMotion === 'true';

  if (!enabled) {
    feedRevealObserver?.disconnect();
    feedRevealObserver = null;
    items.forEach((item) => {
      item.removeAttribute('data-ytr-feed-reveal');
      (item as HTMLElement).style.removeProperty('--ytr-feed-reveal-delay');
    });
    return;
  }

  if (items.length === 0) {
    feedRevealObserver?.disconnect();
    feedRevealObserver = null;
    document.querySelectorAll('[data-ytr-feed-reveal]').forEach((item) => {
      item.removeAttribute('data-ytr-feed-reveal');
      (item as HTMLElement).style.removeProperty('--ytr-feed-reveal-delay');
    });
    return;
  }

  const observer = ensureFeedRevealObserver();
  items.forEach((item, index) => {
    const element = item as HTMLElement;
    if (element.getAttribute('data-ytr-feed-reveal') === 'visible') return;
    element.style.setProperty('--ytr-feed-reveal-delay', `${Math.min(index % 5, 4) * 18}ms`);
    if (!element.hasAttribute('data-ytr-feed-reveal')) {
      element.setAttribute('data-ytr-feed-reveal', 'pending');
    }
    observer.observe(element);
  });
}

function tagSearchShelves(): void {
  const d = document.documentElement.dataset;
  if (d.ytrHideSearchPeopleWatched !== 'true') return;
  if (!document.querySelector('ytd-search')) return;
  document.querySelectorAll('ytd-search ytd-shelf-renderer').forEach((shelf) => {
    const hasChannelLink = !!shelf.querySelector('a[href*="/@"], a[href*="/channel/"]');
    setElementFlag(shelf, 'data-ytr-search-people-watched', !hasChannelLink);
  });
}

function tagSimpleBadges(): void {
  if (document.documentElement.dataset.ytrHideNewBadge !== 'true') return;
  if (!document.querySelector('ytd-badge-supported-renderer')) return;
  document.querySelectorAll('ytd-badge-supported-renderer').forEach((badge) => {
    setElementFlag(badge, 'data-ytr-simple-badge', !!badge.querySelector('.badge-style-type-simple'));
  });
}

function tagFeedItems(): void {
  if (!needsFeedTags()) {
    syncFeedRevealObserver();
    return;
  }
  const items = document.querySelectorAll(FEED_ITEM_SELECTOR);
  if (items.length === 0) {
    tagSearchShelves();
    tagSimpleBadges();
    syncFeedRevealObserver();
    fixAvatarLiveLinks();
    return;
  }

  items.forEach((item) => {
    item.setAttribute('data-ytr-scanned', '');

    // Live streams — type-based only
    if (item.querySelector(
      'ytd-thumbnail-overlay-time-status-renderer[overlay-style="LIVE"], ' +
      '.badge-style-type-live-now, .badge-style-type-live-now-alt'
    )) {
      item.setAttribute('data-ytr-live', 'true');
    }

    // Upcoming / Premieres
    if (item.querySelector('ytd-thumbnail-overlay-time-status-renderer[overlay-style="UPCOMING"]')) {
      item.setAttribute('data-ytr-upcoming', 'true');
    }

    // Mixes
    if (item.querySelector('ytd-radio-renderer, ytd-compact-radio-renderer')) {
      item.setAttribute('data-ytr-mix', 'true');
    }

    if (item.matches('ytd-video-renderer')) {
      setElementFlag(item, 'data-ytr-short-result', !!item.querySelector('a[href^="/shorts"]'));
    }
  });

  tagSearchShelves();
  tagSimpleBadges();
  syncFeedRevealObserver();
  fixAvatarLiveLinks();
}

// --- Avatar: fix live redirect on avatar clicks ---

let avatarClickListenerAdded = false;
const AVATAR_LIVE_LINK_SELECTOR = 'a[href*="/watch?v="]:not([data-ytr-live-fixed]), a[href*="/live/"]:not([data-ytr-live-fixed])';

function fixAvatarLiveLinks(): void {
  if (document.documentElement.dataset.ytrDisableAvatarLive !== 'true') return;

  // Fix href attributes on avatar links pointing to streams
  document.querySelectorAll(AVATAR_LIVE_LINK_SELECTOR).forEach((link) => {
    if (!link.querySelector('yt-avatar-shape, yt-img-shadow, img.yt-core-image')) return;
    const href = link.getAttribute('href') || '';
    if (!href.includes('/watch?v=') && !href.includes('/live/')) return;

    link.setAttribute('data-ytr-live-fixed', 'true');

    const container = link.closest(
      'ytd-rich-item-renderer, ytd-video-renderer, ytd-compact-video-renderer, ' +
      'ytd-video-owner-renderer, ytd-channel-renderer, #owner'
    );
    if (container) {
      const channelLink = container.querySelector(
        'a[href^="/@"], a[href^="/channel/"], a[href^="/c/"]'
      );
      if (channelLink) {
        link.setAttribute('href', channelLink.getAttribute('href') || '');
      }
    }
  });

  // Intercept clicks on avatar links — YouTube may use JS navigation
  if (!avatarClickListenerAdded) {
    avatarClickListenerAdded = true;
    document.addEventListener('click', (e) => {
      if (document.documentElement.dataset.ytrDisableAvatarLive !== 'true') return;
      const avatar = (e.target as HTMLElement).closest('a');
      if (!avatar) return;
      const href = avatar.getAttribute('href') || '';
      if (!href.includes('/watch?v=') && !href.includes('/live/')) return;
      if (!avatar.querySelector('yt-avatar-shape, yt-img-shadow, img.yt-core-image')) return;

      // Find channel URL and redirect there instead
      const container = avatar.closest(
        'ytd-rich-item-renderer, ytd-video-renderer, ytd-compact-video-renderer, ' +
        'ytd-video-owner-renderer, ytd-channel-renderer, #owner'
      );
      if (container) {
        const channelLink = container.querySelector(
          'a[href^="/@"], a[href^="/channel/"], a[href^="/c/"]'
        );
        if (channelLink) {
          e.preventDefault();
          e.stopPropagation();
          const channelUrl = channelLink.getAttribute('href') || '';
          window.location.href = channelUrl;
        }
      }
    }, true);
  }
}


// --- Prefetch: trigger YouTube's lazy loading earlier when videosPerRow > default ---

let prefetchActive = false;

function isBalancedPrefetchEnabled(): boolean {
  return getHomeFeedColumns() > 0;
}

function getHomeGridRoot(): HTMLElement | null {
  return document.querySelector('ytd-browse[page-subtype="home"] ytd-rich-grid-renderer:not(ytd-rich-section-renderer *) > #contents') as HTMLElement | null;
}

function getHomeFeedColumns(): number {
  const value = Number.parseInt(document.documentElement.dataset.ytrVideosPerRow || '', 10);
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function getHomeFeedItemCount(): number {
  return document.querySelectorAll('ytd-browse[page-subtype="home"] ytd-rich-grid-renderer:not(ytd-rich-section-renderer *) > #contents > ytd-rich-item-renderer').length;
}

function getContinuationItem(): HTMLElement | null {
  return document.querySelector('ytd-browse[page-subtype="home"] ytd-rich-grid-renderer:not(ytd-rich-section-renderer *) > #contents > ytd-continuation-item-renderer') as HTMLElement | null
    ?? document.querySelector('ytd-continuation-item-renderer') as HTMLElement | null;
}

function ensurePrefetchObserverRoot(): void {
  const root = getHomeGridRoot();
  if (root === prefetchObservedRoot) return;
  prefetchMutationObserver?.disconnect();
  prefetchObservedRoot = root;
  if (root && prefetchMutationObserver) {
    prefetchMutationObserver.observe(root, { childList: true });
  }
}

function resetPrefetchTracking(): void {
  prefetchBurstCount = 0;
  prefetchLastFeedCount = 0;
  prefetchLastResizeSignal = 0;
  prefetchLastRequestedCount = 0;
  prefetchLastViewportResizeAt = 0;
}

function teardownPrefetch(): void {
  prefetchMutationObserver?.disconnect();
  prefetchMutationObserver = null;
  prefetchObservedRoot = null;

  if (prefetchRetryTimer !== null) {
    window.clearTimeout(prefetchRetryTimer);
    prefetchRetryTimer = null;
  }

  if (prefetchRaf) {
    window.cancelAnimationFrame(prefetchRaf);
    prefetchRaf = 0;
  }

  if (prefetchScrollHandler) {
    window.removeEventListener('scroll', prefetchScrollHandler);
    prefetchScrollHandler = null;
  }

  if (prefetchResizeHandler) {
    window.removeEventListener('resize', prefetchResizeHandler);
    prefetchResizeHandler = null;
  }

  if (prefetchNavigateHandler) {
    document.removeEventListener('yt-navigate-finish', prefetchNavigateHandler);
    prefetchNavigateHandler = null;
  }

  prefetchActive = false;
  resetPrefetchTracking();
}

function schedulePrefetchCheck(delay = 0): void {
  if (!isBalancedPrefetchEnabled()) return;
  if (prefetchRetryTimer !== null) {
    window.clearTimeout(prefetchRetryTimer);
  }
  prefetchRetryTimer = window.setTimeout(() => {
    prefetchRetryTimer = null;
    runPrefetchCheck();
  }, delay);
}

function queuePrefetchCheck(): void {
  if (!isBalancedPrefetchEnabled()) return;
  if (!document.querySelector('ytd-browse[page-subtype="home"]')) return;
  if (prefetchRaf) return;
  prefetchRaf = window.requestAnimationFrame(() => {
    prefetchRaf = 0;
    runPrefetchCheck();
  });
}

function runPrefetchCheck(): void {
  if (document.hidden) return;
  if (!isBalancedPrefetchEnabled()) return;
  if (!document.querySelector('ytd-browse[page-subtype="home"]')) return;
  if (Date.now() - prefetchLastViewportResizeAt < 1400) return;
  ensurePrefetchObserverRoot();
  if (!prefetchObservedRoot) return;
  const columns = getHomeFeedColumns();
  if (columns <= 0) return;

  const continuation = getContinuationItem();
  if (!continuation) return;

  const feedCount = getHomeFeedItemCount();
  const needsBalancedBatch = feedCount > 0 && feedCount % columns !== 0;
  const rect = continuation.getBoundingClientRect();
  const nearViewport = rect.top < window.innerHeight * (needsBalancedBatch ? 6 : 3.5);

  if (!nearViewport) return;

  const now = Date.now();
  const sameFeedCount = feedCount === prefetchLastRequestedCount;
  if (sameFeedCount && now - prefetchLastResizeSignal < 1200) return;

  prefetchLastResizeSignal = now;
  prefetchLastRequestedCount = feedCount;
  window.dispatchEvent(new Event('resize'));

  if (!needsBalancedBatch) {
    prefetchBurstCount = 0;
    prefetchLastFeedCount = feedCount;
    return;
  }

  prefetchBurstCount = feedCount === prefetchLastFeedCount ? prefetchBurstCount + 1 : 0;
  prefetchLastFeedCount = feedCount;

  if (prefetchBurstCount < 4) {
    schedulePrefetchCheck(140 + (prefetchBurstCount * 90));
  }
}

function setupPrefetch(): void {
  if (!isBalancedPrefetchEnabled()) return;
  if (prefetchActive) return;
  prefetchActive = true;
  prefetchMutationObserver = new MutationObserver(() => {
    schedulePrefetchCheck(120);
  });

  const resetPrefetchState = () => {
    resetPrefetchTracking();
    ensurePrefetchObserverRoot();
    schedulePrefetchCheck(220);
  };

  prefetchScrollHandler = () => queuePrefetchCheck();
  prefetchResizeHandler = () => {
    prefetchLastViewportResizeAt = Date.now();
  };
  prefetchNavigateHandler = resetPrefetchState;

  window.addEventListener('scroll', prefetchScrollHandler, { passive: true });
  window.addEventListener('resize', prefetchResizeHandler, { passive: true });
  document.addEventListener('yt-navigate-finish', prefetchNavigateHandler);

  ensurePrefetchObserverRoot();
  schedulePrefetchCheck(900);
  schedulePrefetchCheck(1600);
}

// --- Thumbnail: inject SVG pixelation filter ---

let pixelFilterInjected = false;
let responsiveHomeGridObserver: ResizeObserver | null = null;
let responsiveHomeGridObservedRoot: HTMLElement | null = null;
let responsiveHomeGridResizeListener = false;

function getHomeRichGridContents(): HTMLElement | null {
  return document.querySelector('ytd-browse[page-subtype="home"] ytd-rich-grid-renderer:not(ytd-rich-section-renderer *) > #contents') as HTMLElement | null;
}

function calculateResponsiveHomeGridColumns(containerWidth: number, desiredColumns: number): number {
  const desired = Math.min(8, Math.max(1, Math.round(desiredColumns)));
  if (desired <= 1) return 1;
  const fullHdContentWidth = 1760;
  const targetCardWidth = Math.min(420, Math.max(180, fullHdContentWidth / desired));
  const minReadableCardWidth = targetCardWidth * 0.78;
  for (let columns = desired; columns > 1; columns -= 1) {
    if ((containerWidth / columns) >= minReadableCardWidth) {
      return columns;
    }
  }
  return 1;
}

function updateResponsiveHomeGridColumns(settings: Settings | null = currentSettings): void {
  if (!settings || settings.videosPerRow <= 0 || !settings.homepageResponsiveGrid) {
    document.documentElement.style.removeProperty('--ytr-responsive-videos-per-row');
    return;
  }
  const contents = getHomeRichGridContents();
  const containerWidth = Math.max(0, contents?.getBoundingClientRect().width || window.innerWidth);
  const columns = calculateResponsiveHomeGridColumns(containerWidth, settings.videosPerRow);
  document.documentElement.style.setProperty('--ytr-responsive-videos-per-row', String(columns));
}

function syncResponsiveHomeGridColumns(settings: Settings): void {
  if (!settings.homepageResponsiveGrid || settings.videosPerRow <= 0) {
    document.documentElement.style.removeProperty('--ytr-responsive-videos-per-row');
    teardownResponsiveHomeGrid();
    return;
  }
  const contents = getHomeRichGridContents();
  if (contents && responsiveHomeGridObservedRoot !== contents) {
    responsiveHomeGridObserver?.disconnect();
    responsiveHomeGridObservedRoot = contents;
    responsiveHomeGridObserver = new ResizeObserver(() => updateResponsiveHomeGridColumns());
    responsiveHomeGridObserver.observe(contents);
  }
  if (!responsiveHomeGridResizeListener) {
    responsiveHomeGridResizeListener = true;
    window.addEventListener('resize', () => updateResponsiveHomeGridColumns(), { passive: true });
    document.addEventListener('yt-navigate-finish', () => window.setTimeout(() => syncResponsiveHomeGridColumns(currentSettings || DEFAULT_SETTINGS), 240));
  }
  updateResponsiveHomeGridColumns(settings);
}

function teardownResponsiveHomeGrid(): void {
  responsiveHomeGridObserver?.disconnect();
  responsiveHomeGridObserver = null;
  responsiveHomeGridObservedRoot = null;
}

function injectPixelFilter(): void {
  if (pixelFilterInjected) return;
  pixelFilterInjected = true;
  const svg = createSvgElement('svg', { width: '0', height: '0', 'aria-hidden': 'true' });
  svg.style.position = 'absolute';
  const defs = createSvgElement('defs');
  const filter = createSvgElement('filter', { id: 'ytr-pixelate', x: '0', y: '0', width: '1', height: '1' });
  filter.append(
    createSvgElement('feFlood', { x: '4', y: '4', height: '2', width: '2' }),
    createSvgElement('feComposite', { width: '10', height: '10' }),
    createSvgElement('feTile', { result: 'a' }),
    createSvgElement('feComposite', { in: 'SourceGraphic', in2: 'a', operator: 'in' }),
    createSvgElement('feMorphology', { operator: 'dilate', radius: '5' }),
  );
  defs.appendChild(filter);
  svg.appendChild(defs);
  document.documentElement.appendChild(svg);
}

// Playback Speed Memory

let speedListenersSetup = false;
let playbackSpeedTimers: number[] = [];
let autoSkipAdsTimers: number[] = [];
let autoSkipAdsInterval: number | null = null;
let qualityListenersSetup = false;
let qualityDispatchTimers: number[] = [];
let playbackSpeedVideo: HTMLVideoElement | null = null;
let playbackSpeedPlayerObserver: MutationObserver | null = null;
let observedPlaybackPlayer: HTMLElement | null = null;
let autoSkipAdsObserver: MutationObserver | null = null;
let observedAutoSkipAdsPlayer: HTMLElement | null = null;
let playbackRateApplyingUntil = 0;
let pagePlaybackOverride: number | null = null;
let playbackSpeedPageKey = '';
let playbackSpeedMenuSelectionTimer: number | null = null;
let playbackSpeedMenuIntentUntil = 0;
let playbackPointerHoldActive = false;
let playbackPointerHoldStartRate: number | null = null;
let playbackKeyboardHoldActive = false;
let playbackKeyboardHoldStartRate: number | null = null;
let playbackTemporaryBoostUntil = 0;
let autoSkipAdsSetup = false;
let lastAutoSkipAdsClickAt = 0;
let autoSkipAdsInFlight = false;
let playbackSpeedInitialApplyUntil = 0;
let playbackRateBubbleHideTimer: number | null = null;
let playbackRateBubbleEl: HTMLElement | null = null;
const PLAYBACK_RATE_BUBBLE_HIDE_DELAY_MS = 1800;

function isPlaybackNativeHoldActive(): boolean {
  return playbackPointerHoldActive || playbackKeyboardHoldActive;
}

function getCurrentWatchPlaybackKey(): string {
  const url = new URL(window.location.href);
  return `${url.pathname}?v=${url.searchParams.get('v') || ''}`;
}

function clampPlaybackRate(value: number | null | undefined): number | null {
  if (!Number.isFinite(value)) return null;
  const numericValue = Number(value);
  if (numericValue <= 0) return null;
  return Math.min(16, Math.max(0.25, Math.round(numericValue * 100) / 100));
}

function isWatchPlaybackPage(): boolean {
  return window.location.pathname.startsWith('/watch')
    || window.location.pathname.startsWith('/shorts/');
}

function getDesiredPlaybackRate(settings: Settings | null = currentSettings): number | null {
  const manualOverride = clampPlaybackRate(pagePlaybackOverride);
  if (manualOverride !== null) return manualOverride;
  return clampPlaybackRate(settings?.playbackSpeed);
}

function resetPlaybackOverrideForPage(force = false): void {
  const nextPageKey = getCurrentWatchPlaybackKey();
  if (!force && playbackSpeedPageKey === nextPageKey) return;

  playbackSpeedPageKey = nextPageKey;
  pagePlaybackOverride = null;
  playbackSpeedInitialApplyUntil = Date.now() + 6000;
}

function schedulePlaybackSpeedApply(delays: number[] = [80, 320, 900, 1800]): void {
  playbackSpeedTimers.forEach((timer) => clearTimeout(timer));
  playbackSpeedTimers = [];

  if (!isWatchPlaybackPage()) return;
  if (getDesiredPlaybackRate() === null) return;

  playbackSpeedTimers = delays.map((delay) => window.setTimeout(() => {
    bindPlaybackSpeedVideo(getMainVideoElement());
    applyDesiredPlaybackRate();
  }, delay));
}

function schedulePlaybackSpeedRestore(delay = 80): void {
  window.setTimeout(() => {
    if (isPlaybackNativeHoldActive() || Date.now() <= playbackTemporaryBoostUntil) {
      return;
    }
    bindPlaybackSpeedVideo(getMainVideoElement());
    applyDesiredPlaybackRate();
  }, delay);
}

function applyDesiredPlaybackRate(force = false): void {
  if (!force && (isPlaybackNativeHoldActive() || Date.now() <= playbackTemporaryBoostUntil)) return;

  const manualOverride = clampPlaybackRate(pagePlaybackOverride);
  const target = manualOverride ?? clampPlaybackRate(currentSettings?.playbackSpeed);
  if (target === null) return;
  if (!force && manualOverride === null && Date.now() > playbackSpeedInitialApplyUntil) return;

  const video = playbackSpeedVideo ?? getMainVideoElement();
  if (!video) return;

  if (!force && Math.abs(video.playbackRate - target) < 0.01) return;

  playbackRateApplyingUntil = Date.now() + 220;
  try {
    video.defaultPlaybackRate = target;
  } catch {
    // Some Chromium ad video wrappers reject defaultPlaybackRate writes.
  }
  try {
    video.playbackRate = target;
  } catch {
    // Ignore transient playback rate write failures.
  }
}

function handleObservedPlaybackRateChange(event: Event): void {
  const video = event.currentTarget instanceof HTMLVideoElement
    ? event.currentTarget
    : getMainVideoElement();
  if (!video) return;

  const nextRate = clampPlaybackRate(video.playbackRate);
  if (nextRate === null) return;

  const now = Date.now();
  if (now <= playbackRateApplyingUntil) return;

  if (now <= playbackSpeedMenuIntentUntil) return;

  const desiredRate = getDesiredPlaybackRate();
  const holdStartRate = clampPlaybackRate(playbackPointerHoldStartRate ?? playbackKeyboardHoldStartRate);
  const looksLikeYoutubeHoldBoost = isPlaybackNativeHoldActive()
    && Math.abs(nextRate - 2) < 0.01
    && (holdStartRate === null || Math.abs(holdStartRate - 2) > 0.01);

  if (looksLikeYoutubeHoldBoost) {
    playbackTemporaryBoostUntil = now + 1800;
    return;
  }

  if (now <= playbackTemporaryBoostUntil) {
    if (desiredRate !== null && Math.abs(nextRate - desiredRate) > 0.01) {
      schedulePlaybackSpeedRestore(90);
    }
    return;
  }

  if (desiredRate !== null && Math.abs(nextRate - desiredRate) > 0.01) {
    if (pagePlaybackOverride !== null) {
      schedulePlaybackSpeedRestore(120);
      return;
    }
    if (now <= playbackSpeedInitialApplyUntil) {
      schedulePlaybackSpeedRestore(120);
    }
  }
}

function commitPagePlaybackOverride(rate: number, video: HTMLVideoElement | null = getMainVideoElement()): void {
  const nextRate = clampPlaybackRate(rate);
  if (nextRate === null) return;

  pagePlaybackOverride = nextRate;
  playbackSpeedInitialApplyUntil = 0;
  playbackRateApplyingUntil = Date.now() + 280;

  if (!video) return;
  try {
    video.defaultPlaybackRate = nextRate;
  } catch {
    // Chromium may reject defaultPlaybackRate on transient ad media nodes.
  }
  try {
    video.playbackRate = nextRate;
  } catch {
    // Ignore transient player write failures.
  }
}

function getPlaybackBubbleHost(): HTMLElement | null {
  return document.querySelector('#movie_player, .html5-video-player') as HTMLElement | null;
}

function formatPlaybackRateBubbleLabel(rate: number): string {
  return `${rate.toFixed(1).replace(/\.0$/, '')}x`;
}

function hideNativePlaybackRateBezel(
  container: HTMLElement,
  iconBezel: HTMLElement | null,
  hideIconBezel: boolean,
): void {
  if (container.dataset.ytrPlaybackRateBezel !== 'true') return;

  container.style.display = 'none';
  delete container.dataset.ytrPlaybackRateBezel;

  if (!iconBezel) return;

  if (hideIconBezel) {
    iconBezel.style.display = iconBezel.dataset.ytrPreviousDisplay || '';
    iconBezel.style.visibility = iconBezel.dataset.ytrPreviousVisibility || '';
  }
  if (iconBezel.dataset.ytrPreviousAriaLabel) {
    iconBezel.setAttribute('aria-label', iconBezel.dataset.ytrPreviousAriaLabel);
  } else {
    iconBezel.removeAttribute('aria-label');
  }
  delete iconBezel.dataset.ytrPreviousDisplay;
  delete iconBezel.dataset.ytrPreviousVisibility;
  delete iconBezel.dataset.ytrPreviousAriaLabel;
}

function showNativePlaybackRateBezel(label: string): boolean {
  const host = getPlaybackBubbleHost();
  if (!host) return false;

  const wrapper = host.querySelector('.ytp-bezel-text-wrapper') as HTMLElement | null;
  const text = (wrapper?.querySelector('.ytp-bezel-text') || host.querySelector('.ytp-bezel .ytp-bezel-text')) as HTMLElement | null;
  const iconBezel = host.querySelector('.ytp-bezel[role="status"], .ytp-bezel') as HTMLElement | null;
  const sharedContainer = wrapper && iconBezel && wrapper.parentElement === iconBezel.parentElement
    ? wrapper.parentElement
    : wrapper?.parentElement || iconBezel?.parentElement || iconBezel;
  const container = sharedContainer instanceof HTMLElement ? sharedContainer : null;
  if (!container || !text) return false;
  const hideIconBezel = !!iconBezel && iconBezel !== container && !iconBezel.contains(text);

  playbackRateBubbleEl?.remove();
  playbackRateBubbleEl = null;

  if (playbackRateBubbleHideTimer !== null) {
    clearTimeout(playbackRateBubbleHideTimer);
    playbackRateBubbleHideTimer = null;
  }

  // Fully tear down the previous speed bezel before showing the next one.
  hideNativePlaybackRateBezel(container, iconBezel, hideIconBezel);

  const previousIconDisplay = iconBezel?.dataset.ytrPreviousDisplay ?? iconBezel?.style.display ?? '';
  const previousIconVisibility = iconBezel?.dataset.ytrPreviousVisibility ?? iconBezel?.style.visibility ?? '';
  const previousAriaLabel = iconBezel?.dataset.ytrPreviousAriaLabel ?? iconBezel?.getAttribute('aria-label') ?? '';

  text.textContent = label;
  container.dataset.ytrPlaybackRateBezel = 'true';
  container.style.display = 'block';
  container.style.visibility = 'visible';
  container.style.opacity = '1';
  text.style.display = '';
  if (wrapper) {
    wrapper.style.display = 'block';
    wrapper.style.visibility = 'visible';
    wrapper.style.opacity = '1';
  }
  if (iconBezel) {
    iconBezel.setAttribute('aria-label', `${label} playback speed`);
    iconBezel.dataset.ytrPreviousAriaLabel = previousAriaLabel;
    iconBezel.classList.remove('ytp-bezel-text-hide', 'ytp-bezel-hide');
    if (hideIconBezel) {
      iconBezel.dataset.ytrPreviousDisplay = previousIconDisplay;
      iconBezel.dataset.ytrPreviousVisibility = previousIconVisibility;
      iconBezel.style.display = 'none';
      iconBezel.style.visibility = 'hidden';
    }
  }

  // Restart native bezel animation so each speed step feels like a new volume-style toast.
  container.classList.add('ytp-bezel-text-hide');
  if (wrapper) {
    wrapper.classList.add('ytp-bezel-text-hide');
  }
  void container.offsetWidth;
  container.classList.remove('ytp-bezel-text-hide', 'ytp-bezel-hide');
  if (wrapper) {
    wrapper.classList.remove('ytp-bezel-text-hide', 'ytp-bezel-hide');
  }
  void container.offsetWidth;

  playbackRateBubbleHideTimer = window.setTimeout(() => {
    hideNativePlaybackRateBezel(container, iconBezel, hideIconBezel);
    playbackRateBubbleHideTimer = null;
  }, PLAYBACK_RATE_BUBBLE_HIDE_DELAY_MS);

  return true;
}

function showPlaybackRateBubble(rate: number): void {
  const host = getPlaybackBubbleHost();
  if (!host) return;
  const label = formatPlaybackRateBubbleLabel(rate);

  if (showNativePlaybackRateBezel(label)) return;

  if (window.getComputedStyle(host).position === 'static') {
    host.style.position = 'relative';
  }

  if (!(playbackRateBubbleEl instanceof HTMLElement) || !host.contains(playbackRateBubbleEl)) {
    playbackRateBubbleEl?.remove();
    playbackRateBubbleEl = createHtmlElement('div', 'ytr-playback-rate-bubble');
    host.appendChild(playbackRateBubbleEl);
  }

  playbackRateBubbleEl.textContent = label;
  playbackRateBubbleEl.dataset.visible = 'true';
  playbackRateBubbleEl.style.zIndex = '2147483000';

  if (playbackRateBubbleHideTimer !== null) {
    clearTimeout(playbackRateBubbleHideTimer);
  }

  playbackRateBubbleHideTimer = window.setTimeout(() => {
    if (playbackRateBubbleEl) {
      playbackRateBubbleEl.dataset.visible = 'false';
    }
    playbackRateBubbleHideTimer = null;
  }, PLAYBACK_RATE_BUBBLE_HIDE_DELAY_MS);
}

function getPlaybackRateMenuItem(target: EventTarget | null): HTMLElement | null {
  if (!(target instanceof Element)) return null;
  return target.closest('.ytp-menuitem[role="menuitemradio"], .ytp-panel-menu .ytp-menuitem[role="menuitemradio"]') as HTMLElement | null;
}

function handlePlaybackRateMenuIntent(event: Event): void {
  if (!getPlaybackRateMenuItem(event.target)) return;
  playbackSpeedMenuIntentUntil = Date.now() + 1400;
}

function handlePlaybackRateMenuSelection(event: Event): void {
  if (!getPlaybackRateMenuItem(event.target)) return;

  if (playbackSpeedMenuSelectionTimer !== null) {
    clearTimeout(playbackSpeedMenuSelectionTimer);
  }

  playbackSpeedMenuSelectionTimer = window.setTimeout(() => {
    playbackSpeedMenuSelectionTimer = null;
    const video = getMainVideoElement();
    const nextRate = clampPlaybackRate(video?.playbackRate);
    if (nextRate === null) return;
    commitPagePlaybackOverride(nextRate, video);
    showPlaybackRateBubble(nextRate);
  }, 140);
}

function handlePlaybackMediaLifecycle(): void {
  bindPlaybackSpeedVideo(getMainVideoElement());
  schedulePlaybackSpeedApply([0, 120, 520]);
}

function isPlaybackSurfacePress(target: EventTarget | null): boolean {
  if (!(target instanceof Element)) return false;
  const player = getPlaybackBubbleHost();
  if (!player || !player.contains(target)) return false;
  return !target.closest(
    '.ytp-chrome-bottom,' +
    ' .ytp-chrome-top,' +
    ' .ytp-gradient-bottom,' +
    ' .ytp-gradient-top,' +
    ' .ytp-settings-menu,' +
    ' .ytp-popup,' +
    ' .ytp-menuitem,' +
    ' button,' +
    ' a,' +
    ' input,' +
    ' textarea',
  );
}

function handlePlaybackPointerDown(event: PointerEvent): void {
  if (!isWatchPlaybackPage()) return;
  if (event.button !== 0) return;
  if (!isPlaybackSurfacePress(event.target)) return;

  playbackPointerHoldActive = true;
  playbackPointerHoldStartRate = clampPlaybackRate(getMainVideoElement()?.playbackRate);
}

function handlePlaybackPointerRelease(): void {
  if (!playbackPointerHoldActive) return;

  playbackPointerHoldActive = false;
  finishPlaybackNativeHold(playbackPointerHoldStartRate);
  playbackPointerHoldStartRate = null;
}

function finishPlaybackNativeHold(startRate: number | null): void {
  const video = getMainVideoElement();
  const nextRate = clampPlaybackRate(video?.playbackRate);
  const holdStartRate = clampPlaybackRate(startRate);
  if (nextRate !== null && Math.abs(nextRate - 2) < 0.01 && (holdStartRate === null || Math.abs(holdStartRate - 2) > 0.01)) {
    playbackTemporaryBoostUntil = Date.now() + 900;
  }
  const shouldRestore = Date.now() <= playbackTemporaryBoostUntil + 500;

  if (shouldRestore && getDesiredPlaybackRate() !== null) {
    schedulePlaybackSpeedRestore(120);
    schedulePlaybackSpeedRestore(980);
    schedulePlaybackSpeedRestore(1260);
  }
}

function isPlaybackTextEntryTarget(target: EventTarget | null): boolean {
  return target instanceof Element
    && !!target.closest('input, textarea, select, [contenteditable="true"], [contenteditable="plaintext-only"]');
}

function handlePlaybackKeyboardDown(event: KeyboardEvent): void {
  if (event.code !== 'Space') return;
  if (!isWatchPlaybackPage() || isPlaybackTextEntryTarget(event.target)) return;
  if (playbackKeyboardHoldActive) return;

  playbackKeyboardHoldActive = true;
  playbackKeyboardHoldStartRate = clampPlaybackRate(getMainVideoElement()?.playbackRate);
}

function handlePlaybackKeyboardRelease(event?: KeyboardEvent): void {
  if (event && event.code !== 'Space') return;
  if (!playbackKeyboardHoldActive) return;

  playbackKeyboardHoldActive = false;
  finishPlaybackNativeHold(playbackKeyboardHoldStartRate);
  playbackKeyboardHoldStartRate = null;
}

function bindPlaybackSpeedVideo(video: HTMLVideoElement | null): void {
  if (playbackSpeedVideo === video) return;

  if (playbackSpeedVideo) {
    playbackSpeedVideo.removeEventListener('ratechange', handleObservedPlaybackRateChange);
    playbackSpeedVideo.removeEventListener('loadedmetadata', handlePlaybackMediaLifecycle);
    playbackSpeedVideo.removeEventListener('canplay', handlePlaybackMediaLifecycle);
    playbackSpeedVideo.removeEventListener('playing', handlePlaybackMediaLifecycle);
  }

  playbackSpeedVideo = video;
  if (!video) return;

  video.addEventListener('ratechange', handleObservedPlaybackRateChange);
  video.addEventListener('loadedmetadata', handlePlaybackMediaLifecycle);
  video.addEventListener('canplay', handlePlaybackMediaLifecycle);
  video.addEventListener('playing', handlePlaybackMediaLifecycle);
}

function ensurePlaybackSpeedPlayerObserver(): void {
  const player = document.querySelector('#movie_player, .html5-video-player') as HTMLElement | null;
  if (observedPlaybackPlayer === player && playbackSpeedPlayerObserver) return;

  playbackSpeedPlayerObserver?.disconnect();
  playbackSpeedPlayerObserver = null;
  observedPlaybackPlayer = player;
  if (!player) return;

  playbackSpeedPlayerObserver = new MutationObserver((mutations) => {
    let shouldRefresh = false;
    for (const mutation of mutations) {
      if (mutation.type === 'attributes' || mutation.addedNodes.length || mutation.removedNodes.length) {
        shouldRefresh = true;
        break;
      }
    }

    if (!shouldRefresh) return;
    bindPlaybackSpeedVideo(getMainVideoElement());
    schedulePlaybackSpeedApply([0, 120, 520]);
  });

  playbackSpeedPlayerObserver.observe(player, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: ['class', 'src'],
  });
}

function handlePlaybackCtrlWheel(event: WheelEvent): void {
  if (!event.ctrlKey || event.altKey || event.metaKey) return;
  if (!isWatchPlaybackPage()) return;

  const player = getPlaybackBubbleHost();
  if (!(player instanceof HTMLElement)) return;
  if (!(event.target instanceof Node) || !player.contains(event.target)) return;
  if (event.target instanceof Element && event.target.closest('.ytp-menuitem, .ytp-settings-menu, .ytp-popup, textarea, input')) return;

  const video = getMainVideoElement();
  if (!video) return;

  event.preventDefault();
  event.stopPropagation();

  const direction = event.deltaY < 0 ? 1 : -1;
  const currentRate = clampPlaybackRate(video.playbackRate) ?? 1;
  const nextRate = clampPlaybackRate(Math.round((currentRate + direction * 0.1) * 10) / 10);
  if (nextRate === null) return;
  if (Math.abs(nextRate - currentRate) < 0.001) {
    showPlaybackRateBubble(currentRate);
    return;
  }

  commitPagePlaybackOverride(nextRate, video);
  showPlaybackRateBubble(nextRate);
}

function setupPlaybackSpeed(s: Settings): void {
  if (!speedListenersSetup) {
    speedListenersSetup = true;
    document.addEventListener('yt-navigate-finish', () => {
      resetPlaybackOverrideForPage(true);
      bindPlaybackSpeedVideo(getMainVideoElement());
      ensurePlaybackSpeedPlayerObserver();
      schedulePlaybackSpeedApply([0, 120, 520, 1200]);
    });
    document.addEventListener('yt-player-updated', () => {
      bindPlaybackSpeedVideo(getMainVideoElement());
      ensurePlaybackSpeedPlayerObserver();
      schedulePlaybackSpeedApply([0, 120, 520, 1200]);
    }, true);
    document.addEventListener('yt-page-data-updated', () => {
      bindPlaybackSpeedVideo(getMainVideoElement());
      ensurePlaybackSpeedPlayerObserver();
      schedulePlaybackSpeedApply([0, 120, 520, 1200]);
    }, true);
    document.addEventListener('pointerdown', handlePlaybackRateMenuIntent, true);
    document.addEventListener('keydown', handlePlaybackRateMenuIntent, true);
    document.addEventListener('play', handlePlaybackMediaLifecycle, true);
    document.addEventListener('playing', handlePlaybackMediaLifecycle, true);
    document.addEventListener('durationchange', handlePlaybackMediaLifecycle, true);
    document.addEventListener('click', handlePlaybackRateMenuSelection, true);
    document.addEventListener('pointerdown', handlePlaybackPointerDown, true);
    document.addEventListener('pointerup', handlePlaybackPointerRelease, true);
    document.addEventListener('pointercancel', handlePlaybackPointerRelease, true);
    document.addEventListener('keydown', handlePlaybackKeyboardDown, true);
    document.addEventListener('keyup', handlePlaybackKeyboardRelease, true);
    window.addEventListener('blur', () => handlePlaybackKeyboardRelease());
    document.addEventListener('wheel', handlePlaybackCtrlWheel, { capture: true, passive: false });
  }

  if (!isWatchPlaybackPage()) return;

  resetPlaybackOverrideForPage();
  bindPlaybackSpeedVideo(getMainVideoElement());
  ensurePlaybackSpeedPlayerObserver();
  schedulePlaybackSpeedApply();
}

function scheduleAutoSkipAdsScan(delays: number[] = [0, 160, 420, 900]): void {
  autoSkipAdsTimers.forEach((timer) => clearTimeout(timer));
  autoSkipAdsTimers = [];

  if (!isWatchPlaybackPage() || !currentSettings?.autoSkipAds) return;

  autoSkipAdsTimers = delays.map((delay) => window.setTimeout(() => {
    void tryAutoSkipAds();
  }, delay));
}

function hasVisibleAdUi(player: ParentNode): boolean {
  const candidates = player.querySelectorAll(
    '.ytp-ad-player-overlay,' +
    ' .ytp-ad-module,' +
    ' .video-ads,' +
    ' .ytp-ad-player-overlay-layout,' +
    ' .ytp-ad-text,' +
    ' .ytp-ad-skip-button,' +
    ' .ytp-ad-skip-button-modern,' +
    ' .ytp-skip-ad-button,' +
    ' .ytp-ad-skip-button-container,' +
    ' .ytp-ad-skip-button-slot,' +
    ' .ytp-ad-timed-pie-countdown-container,' +
    ' .ytp-ad-survey-questions'
  );

  return Array.from(candidates).some((candidate) => {
    if (!(candidate instanceof HTMLElement)) return false;
    const style = window.getComputedStyle(candidate);
    if (style.display === 'none' || style.visibility === 'hidden' || Number.parseFloat(style.opacity || '1') === 0) {
      return false;
    }
    const rect = candidate.getBoundingClientRect();
    return rect.width > 0 && rect.height > 0;
  });
}

function isAdShowing(): boolean {
  const player = document.querySelector('#movie_player, .html5-video-player') as HTMLElement | null;
  if (!player) return false;
  return player.classList.contains('ad-showing')
    || player.classList.contains('ad-interrupting')
    || !!getVisibleAdSkipButton()
    || hasVisibleAdUi(player);
}

function getVisibleAdSkipButton(): HTMLElement | null {
  const player = document.querySelector('#movie_player, .html5-video-player');
  if (!(player instanceof HTMLElement)) return null;

  const candidates = Array.from(player.querySelectorAll([
    '.ytp-ad-skip-button',
    '.ytp-ad-skip-button-modern',
    '.ytp-skip-ad-button',
    '.ytp-ad-skip-button-container',
    '.ytp-ad-skip-button-slot',
    '.ytp-ad-skip-button-slot button',
    '.ytp-ad-skip-button-container button',
    '.ytp-ad-player-overlay button',
    '.ytp-ad-player-overlay [role="button"]',
    '.video-ads button',
    '.video-ads [role="button"]',
    '.videoAdUiSkipButton',
    'button[class*="ytp-ad-skip-button"]',
    'button[class*="skip-ad"]',
    '[role="button"][class*="skip-ad"]',
  ].join(', ')));

  for (const candidate of candidates) {
    if (!(candidate instanceof HTMLButtonElement || candidate instanceof HTMLElement)) continue;
    const button = resolveClickableButtonCandidate(candidate);
    if (!button) continue;
    if (button instanceof HTMLButtonElement && button.disabled) continue;
    const label = [
      button.getAttribute('aria-label'),
      button.textContent,
      button.getAttribute('title'),
    ].filter(Boolean).join(' ').toLowerCase();
    const className = typeof button.className === 'string' ? button.className : '';
    const hasSkipSignal = /(skip|пропуст)/i.test(label)
      || /ytp-ad-skip-button|ytp-skip-ad-button|videoAdUiSkipButton|skip-ad/i.test(className);
    if (!hasSkipSignal) continue;
    const style = window.getComputedStyle(button);
    if (style.display === 'none' || style.visibility === 'hidden' || Number.parseFloat(style.opacity || '1') === 0) continue;
    const rect = button.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) continue;
    return button;
  }

  return null;
}

async function tryAutoSkipAds(): Promise<void> {
  if (!currentSettings?.autoSkipAds || !isWatchPlaybackPage()) return;
  if (autoSkipAdsInFlight) return;
  if (!isAdShowing() && !getVisibleAdSkipButton()) return;

  const now = Date.now();
  if (now - lastAutoSkipAdsClickAt < 180) return;

  autoSkipAdsInFlight = true;
  try {
    const bridgeResult = await requestPageBridge<PageBridgeResponse>('clickAdSkip', {}, 480);

    if (bridgeResult?.clicked) {
      lastAutoSkipAdsClickAt = Date.now();
      return;
    }

    const fallbackSkipButton = getVisibleAdSkipButton();
    if (fallbackSkipButton && dispatchElementActivation(fallbackSkipButton)) {
      lastAutoSkipAdsClickAt = Date.now();
    }
  } finally {
    autoSkipAdsInFlight = false;
  }
}

function ensureAutoSkipAdsPolling(): void {
  if (!currentSettings?.autoSkipAds || !isWatchPlaybackPage()) {
    if (autoSkipAdsInterval !== null) {
      clearInterval(autoSkipAdsInterval);
      autoSkipAdsInterval = null;
    }
    return;
  }

  if (autoSkipAdsInterval !== null) return;

  autoSkipAdsInterval = window.setInterval(() => {
    if (!currentSettings?.autoSkipAds || !isWatchPlaybackPage()) return;
    if (!isAdShowing() && !getVisibleAdSkipButton()) return;
    void tryAutoSkipAds();
  }, 120);
}

function ensureAutoSkipAdsObserver(): void {
  const player = document.querySelector('#movie_player, .html5-video-player') as HTMLElement | null;
  if (observedAutoSkipAdsPlayer === player && autoSkipAdsObserver) return;

  autoSkipAdsObserver?.disconnect();
  autoSkipAdsObserver = null;
  observedAutoSkipAdsPlayer = player;
  if (!player) return;

  autoSkipAdsObserver = new MutationObserver(() => {
    ensureAutoSkipAdsPolling();
    scheduleAutoSkipAdsScan([0, 120, 360]);
  });

  autoSkipAdsObserver.observe(player, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: ['class', 'style', 'hidden'],
  });
}

function teardownAutoSkipAds(): void {
  autoSkipAdsTimers.forEach((timer) => clearTimeout(timer));
  autoSkipAdsTimers = [];
  if (autoSkipAdsInterval !== null) {
    clearInterval(autoSkipAdsInterval);
    autoSkipAdsInterval = null;
  }
  autoSkipAdsObserver?.disconnect();
  autoSkipAdsObserver = null;
  observedAutoSkipAdsPlayer = null;
  void requestPageBridge('syncAutoSkipAds', { enabled: false }, 480);
}

function setupAutoSkipAds(s: Settings): void {
  if (!autoSkipAdsSetup) {
    autoSkipAdsSetup = true;
    document.addEventListener('yt-navigate-finish', () => {
      if (!currentSettings?.autoSkipAds || !isWatchPlaybackPage()) {
        teardownAutoSkipAds();
        return;
      }
      ensureAutoSkipAdsObserver();
      ensureAutoSkipAdsPolling();
      scheduleAutoSkipAdsScan([180, 640, 1400]);
    });
    document.addEventListener('yt-player-updated', () => {
      if (!currentSettings?.autoSkipAds || !isWatchPlaybackPage()) {
        teardownAutoSkipAds();
        return;
      }
      ensureAutoSkipAdsObserver();
      ensureAutoSkipAdsPolling();
      scheduleAutoSkipAdsScan([0, 180, 640]);
    }, true);
    document.addEventListener('yt-page-data-updated', () => {
      if (!currentSettings?.autoSkipAds || !isWatchPlaybackPage()) {
        teardownAutoSkipAds();
        return;
      }
      ensureAutoSkipAdsObserver();
      ensureAutoSkipAdsPolling();
      scheduleAutoSkipAdsScan([0, 180, 640]);
    }, true);
    document.addEventListener('play', () => {
      ensureAutoSkipAdsPolling();
      scheduleAutoSkipAdsScan([0, 180, 640]);
    }, true);
    document.addEventListener('playing', () => {
      ensureAutoSkipAdsPolling();
      scheduleAutoSkipAdsScan([0, 180, 640]);
    }, true);
  }

  if (!s.autoSkipAds || !isWatchPlaybackPage()) {
    teardownAutoSkipAds();
    return;
  }

  void requestPageBridge('syncAutoSkipAds', { enabled: true }, 480);
  ensureAutoSkipAdsObserver();
  ensureAutoSkipAdsPolling();
  scheduleAutoSkipAdsScan();
}

function scheduleDefaultQualityDispatch(quality: string, delays: number[]): void {
  qualityDispatchTimers.forEach((timer) => clearTimeout(timer));
  qualityDispatchTimers = delays.map((delay) => window.setTimeout(() => {
    injectDefaultQualityBridge();
    dispatchDefaultQualityBridge(getEffectiveDefaultQuality(currentSettings) || quality);
  }, delay));
}

function setupDefaultQuality(s: Settings): void {
  const quality = getEffectiveDefaultQuality(s);
  if (quality === 'auto' && !qualityBridgeInjected) return;
  injectDefaultQualityBridge();
  scheduleDefaultQualityDispatch(quality, [40, 420, 1200, 2400]);

  if (qualityListenersSetup) return;
  qualityListenersSetup = true;

  const reapplyQuality = () => {
    const nextQuality = getEffectiveDefaultQuality(currentSettings);
    if (nextQuality === 'auto' && !qualityBridgeInjected) return;
    injectDefaultQualityBridge();
    scheduleDefaultQualityDispatch(nextQuality, [80, 560, 1500, 2600]);
  };

  document.addEventListener('yt-navigate-finish', reapplyQuality);
  document.addEventListener('yt-player-updated', reapplyQuality, true);
  document.addEventListener('yt-page-data-updated', reapplyQuality, true);
  document.addEventListener('play', reapplyQuality, true);
}

// Watch Timer & Time Limit

let timerInterval: ReturnType<typeof setInterval> | null = null;
let timerElement: HTMLElement | null = null;
let blockOverlay: HTMLElement | null = null;
let timerNavigationSetup = false;

async function updateTimerDisplay(): Promise<void> {
  const s = currentSettings;
  if (!s) return;

  const minutes = await getWatchTime();

  // Update timer display
  if (s.watchTimerEnabled) {
    if (!timerElement) {
      timerElement = document.createElement('div');
      timerElement.id = 'ytr-watch-timer';
      document.body.appendChild(timerElement);
    }
    const hrs = Math.floor(minutes / 60);
    const mins = Math.floor(minutes % 60);
    timerElement.textContent = hrs > 0 ? `${hrs}h ${mins}m` : `${mins}m`;

    if (s.watchTimeLimitMinutes > 0 && minutes >= s.watchTimeLimitMinutes * 0.8) {
      timerElement.setAttribute('data-ytr-timer-warn', 'true');
    } else {
      timerElement.removeAttribute('data-ytr-timer-warn');
    }
  }

  // Check time limit — works on all pages
  if (s.watchTimeLimitMinutes > 0 && minutes >= s.watchTimeLimitMinutes) {
    const dismissed = await getBlockDismissed();
    if (!dismissed && !blockOverlay) {
      showBlockOverlay(Math.floor(minutes));
    }
  } else if (blockOverlay) {
    blockOverlay.remove();
    blockOverlay = null;
    await setBlockDismissed(false); // Reset if limit is no longer exceeded
  }
}

function setupWatchTimer(s: Settings): void {
  // Clean up existing timer display if disabled
  if (!s.watchTimerEnabled && timerElement) {
    timerElement.remove();
    timerElement = null;
  }

  // Remove block overlay if limit is disabled
  if (s.watchTimeLimitMinutes <= 0 && blockOverlay) {
    blockOverlay.remove();
    blockOverlay = null;
  }

  if (!s.watchTimerEnabled && s.watchTimeLimitMinutes <= 0) {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    return;
  }

  // Increment watch time every minute
  if (!timerInterval) {
    timerInterval = setInterval(async () => {
      if (!currentSettings?.watchTimerEnabled && !(currentSettings && currentSettings.watchTimeLimitMinutes > 0)) return;
      // Track time if tab is visible OR if a video is playing (background playback)
      const video = getMainVideoElement();
      const isVideoPlaying = video && !video.paused && !video.ended && video.readyState > 2;
      if (document.hidden && !isVideoPlaying) return;
      await addWatchTime(1);
      updateTimerDisplay();
    }, 60_000);
  }

  // Re-check on SPA navigation (works on all YT pages)
  if (!timerNavigationSetup) {
    timerNavigationSetup = true;
    document.addEventListener('yt-navigate-finish', () => {
      setTimeout(updateTimerDisplay, 500);
    });
  }

  // Immediate check (reacts to setting changes without reload)
  setTimeout(updateTimerDisplay, 500);
}

function showBlockOverlay(minutes: number): void {
  // Remove existing overlay before creating new one (for repeat mode)
  if (blockOverlay) {
    blockOverlay.remove();
    blockOverlay = null;
  }

  const isRu = getContentLocale() === 'ru';
  const limit = Math.max(currentSettings?.watchTimeLimitMinutes || minutes, 1);
  const progress = clamp(Math.round((minutes / limit) * 100), 0, 100);

  blockOverlay = document.createElement('div');
  blockOverlay.id = 'ytr-block-overlay';
  const aura = createHtmlElement('div', 'ytr-block-aura');
  const content = createHtmlElement('div', 'ytr-block-content');
  const iconShell = createHtmlElement('div', 'ytr-block-icon-shell');
  iconShell.appendChild(createSvgFromMarkup(
    '<svg viewBox="0 0 24 24" width="64" height="64" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>',
  ));
  const meta = createHtmlElement('div', 'ytr-block-meta');
  meta.append(
    createHtmlElement('span', 'ytr-block-pill', `${minutes} ${isRu ? 'мин' : 'min'}`),
    createHtmlElement('span', 'ytr-block-pill ytr-block-pill-progress', `${progress}%`),
  );
  const title = createHtmlElement('h2', 'ytr-block-title', isRu ? 'Дневной лимит достигнут' : 'Daily limit reached');
  const message = createHtmlElement(
    'p',
    'ytr-block-message',
    isRu
      ? `Вы смотрите YouTube уже ${minutes} минут сегодня. Сделайте перерыв!`
      : `You've been watching YouTube for ${minutes} minutes today. Take a break!`,
  );
  const footnote = createHtmlElement(
    'div',
    'ytr-block-footnote',
    isRu
      ? 'Изменить лимит можно в popup расширения'
      : 'You can change the limit in the extension popup',
  );
  const actions = createHtmlElement('div', 'ytr-block-actions');
  const closeButton = createHtmlElement('button', 'ytr-block-close', isRu ? 'Продолжить' : 'Continue anyway');
  actions.appendChild(closeButton);
  content.append(iconShell, meta, title, message, footnote, actions);
  blockOverlay.append(aura, content);

  closeButton.addEventListener('click', async () => {
    blockOverlay?.remove();
    blockOverlay = null;
    if (!currentSettings?.watchTimeLimitBlockRepeat) {
      // Non-repeat mode: persist dismissed for the rest of the day
      await setBlockDismissed(true);
    } else {
      // Repeat mode: dismiss temporarily, will re-show on next interval
      // Don't persist — let it show again next minute
    }
  });

  document.body.appendChild(blockOverlay);
}

// --- Toast notification ---

function showYtrToast(message: string): void {
  const existing = document.querySelector('.ytr-toast');
  if (existing) existing.remove();

  const toast = document.createElement('div');
  toast.className = 'ytr-toast';
  toast.textContent = message;
  document.body.appendChild(toast);
  setTimeout(() => toast.classList.add('ytr-toast-visible'), 10);
  setTimeout(() => {
    toast.classList.remove('ytr-toast-visible');
    setTimeout(() => toast.remove(), 300);
  }, 3000);
}

const GOOGLE_ICON_SVGS = {
  photoCamera: `<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><path d="M0 0h24v24H0V0z" fill="none"/><circle cx="12" cy="12" r="3" fill="currentColor"/><path d="M20 4h-3.17l-1.24-1.35c-.37-.41-.91-.65-1.47-.65H9.88c-.56 0-1.1.24-1.48.65L7.17 4H4c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm-8 13c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5z" fill="currentColor"/></svg>`,
  palette: `<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M12 2C6.49 2 2 6.49 2 12s4.49 10 10 10c1.38 0 2.5-1.12 2.5-2.5 0-.61-.23-1.2-.64-1.67-.08-.1-.13-.21-.13-.33 0-.28.22-.5.5-.5H16c3.31 0 6-2.69 6-6 0-4.96-4.49-9-10-9zm5.5 11c-.83 0-1.5-.67-1.5-1.5S16.67 10 17.5 10 19 10.67 19 11.5 18.33 13 17.5 13zm-3-4C13.67 9 13 8.33 13 7.5S13.67 6 14.5 6 16 6.67 16 7.5 15.33 9 14.5 9zm-8 4C5.67 13 5 12.33 5 11.5S5.67 10 6.5 10 8 10.67 8 11.5 7.33 13 6.5 13zm3-4C8.67 9 8 8.33 8 7.5S8.67 6 9.5 6 11 6.67 11 7.5 10.33 9 9.5 9z" fill="currentColor"/></svg>`,
  colorize: `<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M20.71 5.63 18.37 3.29c-.39-.39-1.02-.39-1.41 0l-3.12 3.12-1.23-1.21c-.39-.39-1.02-.38-1.41 0-.39.39-.39 1.02 0 1.41l.72.72-8.77 8.77c-.1.1-.15.22-.15.36v4.04c0 .28.22.5.5.5h4.04c.13 0 .26-.05.35-.15l8.77-8.77.72.72c.39.39 1.02.39 1.41 0 .39-.39.39-1.02 0-1.41l-1.22-1.22 3.12-3.12c.41-.4.41-1.03.02-1.42zM6.92 19 5 17.08l8.06-8.06 1.92 1.92L6.92 19z" fill="currentColor"/></svg>`,
} as const;

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

type RgbColor = { r: number; g: number; b: number };
type HsvColor = { h: number; s: number; v: number };

function normalizeHexColor(value: string, fallback = '#ffffff'): string {
  const normalized = value.trim().replace(/^#?/, '#').toLowerCase();
  return /^#[0-9a-f]{6}$/i.test(normalized) ? normalized : fallback;
}

function componentToHex(value: number): string {
  return Math.round(clamp(value, 0, 255)).toString(16).padStart(2, '0');
}

function rgbToHex(color: RgbColor): string {
  return `#${componentToHex(color.r)}${componentToHex(color.g)}${componentToHex(color.b)}`;
}

function hexToRgb(hex: string): RgbColor | null {
  const normalized = normalizeHexColor(hex, '');
  if (!normalized) return null;

  const parsed = Number.parseInt(normalized.slice(1), 16);
  if (Number.isNaN(parsed)) return null;

  return {
    r: (parsed >> 16) & 255,
    g: (parsed >> 8) & 255,
    b: parsed & 255,
  };
}

function parseRgbChannels(value: string): RgbColor | null {
  const match = value.match(/rgba?\(([^)]+)\)/i);
  if (!match) return null;

  const parts = match[1]
    .split(',')
    .slice(0, 3)
    .map((part) => Number.parseFloat(part.trim()));

  if (parts.length !== 3 || parts.some((part) => Number.isNaN(part))) return null;

  return {
    r: clamp(parts[0], 0, 255),
    g: clamp(parts[1], 0, 255),
    b: clamp(parts[2], 0, 255),
  };
}

function rgbToHsl(color: RgbColor): { h: number; s: number; l: number } {
  const red = clamp(color.r / 255, 0, 1);
  const green = clamp(color.g / 255, 0, 1);
  const blue = clamp(color.b / 255, 0, 1);
  const max = Math.max(red, green, blue);
  const min = Math.min(red, green, blue);
  const delta = max - min;
  let hue = 0;
  const lightness = (max + min) / 2;
  const saturation = delta === 0 ? 0 : delta / (1 - Math.abs(2 * lightness - 1));

  if (delta !== 0) {
    if (max === red) hue = ((green - blue) / delta) % 6;
    else if (max === green) hue = (blue - red) / delta + 2;
    else hue = (red - green) / delta + 4;
  }

  return {
    h: ((hue * 60) + 360) % 360,
    s: saturation,
    l: lightness,
  };
}

function hueToRgb(p: number, q: number, t: number): number {
  let normalized = t;
  if (normalized < 0) normalized += 1;
  if (normalized > 1) normalized -= 1;
  if (normalized < 1 / 6) return p + (q - p) * 6 * normalized;
  if (normalized < 1 / 2) return q;
  if (normalized < 2 / 3) return p + (q - p) * (2 / 3 - normalized) * 6;
  return p;
}

function hexFromHsl(hue: number, saturation: number, lightness: number): string {
  const normalizedHue = ((hue % 360) + 360) % 360 / 360;
  const normalizedSaturation = clamp(saturation, 0, 100) / 100;
  const normalizedLightness = clamp(lightness, 0, 100) / 100;

  if (normalizedSaturation === 0) {
    const channel = normalizedLightness * 255;
    return rgbToHex({ r: channel, g: channel, b: channel });
  }

  const q = normalizedLightness < 0.5
    ? normalizedLightness * (1 + normalizedSaturation)
    : normalizedLightness + normalizedSaturation - normalizedLightness * normalizedSaturation;
  const p = 2 * normalizedLightness - q;

  return rgbToHex({
    r: hueToRgb(p, q, normalizedHue + 1 / 3) * 255,
    g: hueToRgb(p, q, normalizedHue) * 255,
    b: hueToRgb(p, q, normalizedHue - 1 / 3) * 255,
  });
}

function mixHexColors(first: string, second: string, ratio = 0.5): string {
  const a = hexToRgb(first);
  const b = hexToRgb(second);
  if (!a || !b) return first;

  const weight = clamp(ratio, 0, 1);
  return rgbToHex({
    r: a.r * weight + b.r * (1 - weight),
    g: a.g * weight + b.g * (1 - weight),
    b: a.b * weight + b.b * (1 - weight),
  });
}

function hexToRgbaString(color: string, alpha: number): string {
  const rgb = hexToRgb(color);
  if (!rgb) return `rgba(0, 0, 0, ${clamp(alpha, 0, 1)})`;
  return `rgba(${Math.round(rgb.r)}, ${Math.round(rgb.g)}, ${Math.round(rgb.b)}, ${clamp(alpha, 0, 1)})`;
}

function normalizeThemeSeedColor(color: string): string {
  const rgb = hexToRgb(normalizeHexColor(color, DEFAULT_SETTINGS.interfaceThemeColor));
  if (!rgb) return DEFAULT_SETTINGS.interfaceThemeColor;

  const original = rgbToHex(rgb).toLowerCase();
  const hsl = rgbToHsl(rgb);
  if (hsl.s >= 0.06 && hsl.l >= 0.22 && hsl.l <= 0.92) {
    return original;
  }

  const saturation = hsl.s < 0.06 ? 0.08 : hsl.s;
  const lightness = clamp(hsl.l, 0.22, 0.92);
  return hexFromHsl(hsl.h, saturation * 100, lightness * 100);
}

function sanitizeThemeSeedColor(mode: ResolvedThemeMode, color: string): string {
  const rgb = hexToRgb(normalizeThemeSeedColor(color));
  if (!rgb) return DEFAULT_SETTINGS.interfaceThemeColor;

  const hsl = rgbToHsl(rgb);
  const saturation = hsl.s < 0.08 ? 0.18 : hsl.s;
  const lightness = mode === 'dark'
    ? clamp(hsl.l, 0.58, 0.92)
    : clamp(hsl.l, 0.16, 0.9);

  return hexFromHsl(hsl.h, saturation * 100, lightness * 100);
}

function getThemePrimaryColor(mode: ResolvedThemeMode, seedColor: string): string {
  const rgb = hexToRgb(seedColor) || hexToRgb(DEFAULT_SETTINGS.interfaceThemeColor);
  if (!rgb) return DEFAULT_SETTINGS.interfaceThemeColor;

  const { h, s } = rgbToHsl(rgb);
  if (mode === 'light') {
    return hexFromHsl(h, clamp(s * 100 * 0.46, 34, 56), 40);
  }

  return sanitizeThemeSeedColor('dark', seedColor);
}

function getRelativeLuminance(color: RgbColor): number {
  const normalizeChannel = (value: number): number => {
    const channel = clamp(value, 0, 255) / 255;
    return channel <= 0.03928
      ? channel / 12.92
      : ((channel + 0.055) / 1.055) ** 2.4;
  };

  return (
    0.2126 * normalizeChannel(color.r) +
    0.7152 * normalizeChannel(color.g) +
    0.0722 * normalizeChannel(color.b)
  );
}

function getYoutubeThemeMode(): ResolvedThemeMode {
  const html = document.documentElement;
  if (html.hasAttribute('dark')) return 'dark';

  const app = document.querySelector('ytd-app') as HTMLElement | null;
  if (app?.hasAttribute('dark')) return 'dark';

  const elements = [app, document.body, html].filter(Boolean) as HTMLElement[];
  for (const element of elements) {
    const styles = window.getComputedStyle(element);
    const candidates = [
      styles.getPropertyValue('--yt-spec-base-background'),
      styles.getPropertyValue('--yt-spec-brand-background-primary'),
      styles.getPropertyValue('--yt-spec-general-background-a'),
      styles.backgroundColor,
    ];

    for (const candidate of candidates) {
      if (/rgba\([^)]*,\s*0(?:\.0+)?\s*\)$/i.test(candidate.trim())) {
        continue;
      }
      const parsed = parseRgbChannels(candidate) || hexToRgb(candidate.trim());
      if (!parsed) continue;
      return getRelativeLuminance(parsed) < 0.42 ? 'dark' : 'light';
    }
  }

  return window.matchMedia?.('(prefers-color-scheme: dark)')?.matches ? 'dark' : 'light';
}

function getRewindLogoColor(settings: Settings | null, mode: ResolvedThemeMode): string {
  const seedColor = normalizeHexColor(settings?.interfaceThemeColor || DEFAULT_SETTINGS.interfaceThemeColor, DEFAULT_SETTINGS.interfaceThemeColor);
  const accentSeed = sanitizeThemeSeedColor(mode, seedColor);
  const primary = getThemePrimaryColor(mode, accentSeed);
  return mode === 'light'
    ? mixHexColors(primary, '#6a6675', 0.44)
    : mixHexColors(accentSeed, '#d7d3e5', 0.42);
}

function buildContentInterfaceThemeTokens(settings: Settings | null, mode: ResolvedThemeMode): Record<string, string> {
  const seedColor = normalizeHexColor(settings?.interfaceThemeColor || DEFAULT_SETTINGS.interfaceThemeColor, DEFAULT_SETTINGS.interfaceThemeColor);
  const accentSeed = sanitizeThemeSeedColor(mode, seedColor);
  const rgb = hexToRgb(accentSeed) || hexToRgb(DEFAULT_SETTINGS.interfaceThemeColor);
  if (!rgb) {
    return {
      '--ytr-ui-primary': DEFAULT_SETTINGS.interfaceThemeColor,
      '--ytr-ui-on-primary': '#ffffff',
      '--ytr-ui-primary-soft': '#2e2639',
      '--ytr-ui-surface': '#18151f',
      '--ytr-ui-surface-high': '#211d29',
      '--ytr-ui-surface-highest': '#312b3a',
      '--ytr-ui-outline': 'rgba(255, 255, 255, 0.08)',
      '--ytr-ui-outline-strong': 'rgba(255, 255, 255, 0.18)',
      '--ytr-ui-text': '#f6f1ff',
      '--ytr-ui-text-muted': '#c7bfd6',
      '--ytr-ui-error': '#ffb4ab',
      '--ytr-ui-error-soft': 'rgba(255, 180, 171, 0.14)',
      '--ytr-ui-shadow': '0 18px 42px rgba(0, 0, 0, 0.32)',
    };
  }

  const { h: accentHue, s: accentSaturation } = rgbToHsl(rgb);
  const neutralHue = (accentHue + 8) % 360;
  const primary = getThemePrimaryColor(mode, accentSeed);

  if (mode === 'light') {
    const primarySoft = hexFromHsl(accentHue, clamp(accentSaturation * 100 * 0.84, 62, 90), 89);
    const surface = hexFromHsl(neutralHue, 18, 97);
    const surfaceHigh = hexFromHsl(neutralHue, 14, 92);
    const surfaceHighest = hexFromHsl(neutralHue, 10, 85);
    const outlineStrong = hexFromHsl(neutralHue, 8, 50);
    const text = hexFromHsl(neutralHue, 10, 13);
    const textMuted = hexFromHsl(neutralHue, 8, 32);
    const error = '#ba1a1a';

    return {
      '--ytr-ui-primary': primary,
      '--ytr-ui-on-primary': '#ffffff',
      '--ytr-ui-primary-soft': primarySoft,
      '--ytr-ui-surface': surface,
      '--ytr-ui-surface-high': surfaceHigh,
      '--ytr-ui-surface-highest': surfaceHighest,
      '--ytr-ui-outline': hexToRgbaString(hexFromHsl(neutralHue, 12, 80), 0.82),
      '--ytr-ui-outline-strong': hexToRgbaString(outlineStrong, 0.94),
      '--ytr-ui-text': text,
      '--ytr-ui-text-muted': textMuted,
      '--ytr-ui-error': error,
      '--ytr-ui-error-soft': hexToRgbaString(error, 0.1),
      '--ytr-ui-shadow': '0 18px 42px rgba(15, 18, 28, 0.14)',
    };
  }

  const primarySoft = hexFromHsl(accentHue, clamp(accentSaturation * 100 * 0.5, 30, 58), 34);
  const surface = hexFromHsl(neutralHue, 9, 12);
  const surfaceHigh = hexFromHsl(neutralHue, 8, 14);
  const surfaceHighest = hexFromHsl(neutralHue, 7, 22);
  const outline = hexFromHsl(neutralHue, 7, 24);
  const outlineStrong = hexFromHsl(neutralHue, 8, 58);
  const text = hexFromHsl(neutralHue, 10, 91);
  const textMuted = hexFromHsl(neutralHue, 8, 76);
  const onPrimary = hexFromHsl(accentHue, clamp(accentSaturation * 100 * 0.42, 24, 48), 21);
  const error = '#ffb4ab';

  return {
    '--ytr-ui-primary': primary,
    '--ytr-ui-on-primary': onPrimary,
    '--ytr-ui-primary-soft': primarySoft,
    '--ytr-ui-surface': surface,
    '--ytr-ui-surface-high': surfaceHigh,
    '--ytr-ui-surface-highest': surfaceHighest,
    '--ytr-ui-outline': hexToRgbaString(outline, 0.92),
    '--ytr-ui-outline-strong': hexToRgbaString(outlineStrong, 0.94),
    '--ytr-ui-text': text,
    '--ytr-ui-text-muted': textMuted,
    '--ytr-ui-error': error,
    '--ytr-ui-error-soft': hexToRgbaString(error, 0.14),
    '--ytr-ui-shadow': '0 18px 42px rgba(0, 0, 0, 0.32)',
  };
}

function applyContentInterfaceThemeTokens(settings: Settings | null = currentSettings): void {
  const root = document.documentElement;
  const modeSetting = settings?.interfaceThemeMode || DEFAULT_SETTINGS.interfaceThemeMode;
  const mode: ResolvedThemeMode = modeSetting === 'auto' ? getYoutubeThemeMode() : modeSetting;
  const tokens = buildContentInterfaceThemeTokens(settings, mode);

  for (const [name, value] of Object.entries(tokens)) {
    root.style.setProperty(name, value);
  }

  root.dataset.ytrThemeMode = mode;
}

function rgbToHsv(color: RgbColor): HsvColor {
  const r = clamp(color.r / 255, 0, 1);
  const g = clamp(color.g / 255, 0, 1);
  const b = clamp(color.b / 255, 0, 1);
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;

  let hue = 0;
  if (delta > 0) {
    if (max === r) {
      hue = 60 * (((g - b) / delta) % 6);
    } else if (max === g) {
      hue = 60 * (((b - r) / delta) + 2);
    } else {
      hue = 60 * (((r - g) / delta) + 4);
    }
  }

  if (hue < 0) hue += 360;

  return {
    h: hue,
    s: max === 0 ? 0 : delta / max,
    v: max,
  };
}

function hsvToRgb(color: HsvColor): RgbColor {
  const hue = ((color.h % 360) + 360) % 360;
  const saturation = clamp(color.s, 0, 1);
  const value = clamp(color.v, 0, 1);
  const chroma = value * saturation;
  const segment = hue / 60;
  const x = chroma * (1 - Math.abs((segment % 2) - 1));
  const match = value - chroma;

  let red = 0;
  let green = 0;
  let blue = 0;

  if (segment >= 0 && segment < 1) {
    red = chroma;
    green = x;
  } else if (segment < 2) {
    red = x;
    green = chroma;
  } else if (segment < 3) {
    green = chroma;
    blue = x;
  } else if (segment < 4) {
    green = x;
    blue = chroma;
  } else if (segment < 5) {
    red = x;
    blue = chroma;
  } else {
    red = chroma;
    blue = x;
  }

  return {
    r: Math.round((red + match) * 255),
    g: Math.round((green + match) * 255),
    b: Math.round((blue + match) * 255),
  };
}

function dataUrlToBlob(dataUrl: string): Blob {
  const [meta, data = ''] = dataUrl.split(',');
  const mime = meta.match(/data:([^;]+)/)?.[1] || 'image/png';
  const decoded = atob(data);
  const bytes = new Uint8Array(decoded.length);
  for (let i = 0; i < decoded.length; i++) {
    bytes[i] = decoded.charCodeAt(i);
  }
  return new Blob([bytes], { type: mime });
}

async function resolveImageBlob(src: string): Promise<Blob> {
  if (src.startsWith('data:')) {
    return dataUrlToBlob(src);
  }

  const response = await fetch(src, {
    credentials: 'omit',
    cache: 'force-cache',
  });

  if (!response.ok) {
    throw new Error(`HTTP ${response.status}`);
  }

  return await response.blob();
}

async function renderBlobToPng(blob: Blob): Promise<Blob> {
  const objectUrl = URL.createObjectURL(blob);

  try {
    const img = await new Promise<HTMLImageElement>((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error('Could not decode image'));
      image.src = objectUrl;
    });

    const canvas = document.createElement('canvas');
    canvas.width = img.naturalWidth || img.width;
    canvas.height = img.naturalHeight || img.height;

    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('Canvas unavailable');

    ctx.drawImage(img, 0, 0);

    return await new Promise<Blob>((resolve, reject) => {
      canvas.toBlob((result) => {
        if (result) resolve(result);
        else reject(new Error('Could not export image'));
      }, 'image/png');
    });
  } finally {
    URL.revokeObjectURL(objectUrl);
  }
}

async function copyImageToClipboard(src: string): Promise<'image' | 'link' | 'failed'> {
  if (!navigator.clipboard) return 'failed';

  const writeImage = async (imageSrc: string): Promise<void> => {
    const pngBlobPromise = resolveImageBlob(imageSrc).then((sourceBlob) =>
      sourceBlob.type === 'image/png' ? sourceBlob : renderBlobToPng(sourceBlob)
    );
    await navigator.clipboard.write([new ClipboardItem({ 'image/png': pngBlobPromise })]);
  };

  try {
    if (typeof ClipboardItem !== 'undefined' && navigator.clipboard.write) {
      await writeImage(src);
      return 'image';
    }
  } catch {}

  try {
    if (typeof ClipboardItem !== 'undefined' && navigator.clipboard.write && /^https?:\/\//i.test(src)) {
      const response = await browser.runtime.sendMessage({
        type: 'ytr_fetch_image_data_url',
        url: src,
      }).catch(() => null) as { dataUrl?: string } | null;
      if (response?.dataUrl) {
        await writeImage(response.dataUrl);
        return 'image';
      }
    }
  } catch {}

  try {
    await navigator.clipboard.writeText(src);
    return 'link';
  } catch {
    return 'failed';
  }
}

function buildScreenshotFilename(videoId: string): string {
  const now = new Date();
  const stamp = [
    now.getFullYear(),
    String(now.getMonth() + 1).padStart(2, '0'),
    String(now.getDate()).padStart(2, '0'),
    '-',
    String(now.getHours()).padStart(2, '0'),
    String(now.getMinutes()).padStart(2, '0'),
    String(now.getSeconds()).padStart(2, '0'),
  ].join('');
  return `frame-${videoId}-${stamp}.png`;
}

async function triggerDownload(src: string, filename: string): Promise<void> {
  let downloadUrl = src;
  let shouldRevoke = false;

  try {
    if (src.startsWith('data:')) {
      downloadUrl = URL.createObjectURL(dataUrlToBlob(src));
      shouldRevoke = true;
    } else {
      const response = await fetch(src);
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const blob = await response.blob();
      downloadUrl = URL.createObjectURL(blob);
      shouldRevoke = true;
    }
  } catch {
    if (!(src.startsWith('data:') || src.startsWith('blob:'))) {
      const backgroundDownload = await browser.runtime.sendMessage({
        type: 'ytr_download_url',
        url: src,
        filename,
      }).catch(() => null) as { ok?: boolean } | null;
      if (backgroundDownload?.ok) return;

      const fallbackLink = document.createElement('a');
      fallbackLink.href = src;
      fallbackLink.download = filename;
      fallbackLink.rel = 'noopener';
      fallbackLink.click();
      return;
    }
  }

  const link = document.createElement('a');
  link.href = downloadUrl;
  link.download = filename;
  link.rel = 'noopener';
  link.style.display = 'none';
  document.body.appendChild(link);
  link.click();
  requestAnimationFrame(() => {
    link.remove();
    if (shouldRevoke) {
      URL.revokeObjectURL(downloadUrl);
    }
  });
}

function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const image = new Image();
    if (/^https?:\/\//.test(src)) {
      image.crossOrigin = 'anonymous';
    }
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error('Could not decode image'));
    image.src = src;
  });
}

function getImageFingerprint(image: HTMLImageElement): string | null {
  try {
    const canvas = document.createElement('canvas');
    canvas.width = 12;
    canvas.height = 12;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return null;
    ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
    const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
    const luminance: number[] = [];
    let total = 0;

    for (let i = 0; i < data.length; i += 4) {
      const value = Math.round(data[i] * 0.299 + data[i + 1] * 0.587 + data[i + 2] * 0.114);
      luminance.push(value);
      total += value;
    }

    const threshold = total / luminance.length;
    return luminance.map((value) => (value >= threshold ? '1' : '0')).join('');
  } catch {
    return null;
  }
}

function waitForAnimationFrame(): Promise<void> {
  return new Promise((resolve) => requestAnimationFrame(() => resolve()));
}

function getVisibleVideoRect(video: HTMLVideoElement): DOMRect | null {
  const rect = video.getBoundingClientRect();
  const left = clamp(rect.left, 0, window.innerWidth);
  const top = clamp(rect.top, 0, window.innerHeight);
  const right = clamp(rect.right, 0, window.innerWidth);
  const bottom = clamp(rect.bottom, 0, window.innerHeight);
  const width = right - left;
  const height = bottom - top;

  if (width < 4 || height < 4) return null;
  return new DOMRect(left, top, width, height);
}

async function captureVisibleTab(): Promise<string> {
  const response = await browser.runtime.sendMessage({
    type: 'ytr_capture_visible_tab',
  }) as CaptureVisibleTabResponse;

  if (!response?.dataUrl) {
    throw new Error(response?.error || 'Could not capture visible tab');
  }

  return response.dataUrl;
}

async function captureRawVideoFrame(video: HTMLVideoElement): Promise<string> {
  if (!video.videoWidth || !video.videoHeight || video.readyState < 2) {
    throw new Error('Video frame is not ready');
  }

  const canvas = document.createElement('canvas');
  canvas.width = video.videoWidth;
  canvas.height = video.videoHeight;

  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Canvas unavailable');

  ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
  return canvas.toDataURL('image/png');
}

async function cropDataUrlToRect(dataUrl: string, rect: DOMRect): Promise<string> {
  const image = await loadImage(dataUrl);
  const scaleX = image.naturalWidth / window.innerWidth;
  const scaleY = image.naturalHeight / window.innerHeight;

  const cropX = Math.max(0, Math.round(rect.x * scaleX));
  const cropY = Math.max(0, Math.round(rect.y * scaleY));
  const cropWidth = Math.max(1, Math.round(rect.width * scaleX));
  const cropHeight = Math.max(1, Math.round(rect.height * scaleY));

  const canvas = document.createElement('canvas');
  canvas.width = cropWidth;
  canvas.height = cropHeight;

  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Canvas unavailable');

  ctx.drawImage(
    image,
    cropX,
    cropY,
    cropWidth,
    cropHeight,
    0,
    0,
    cropWidth,
    cropHeight,
  );

  return canvas.toDataURL('image/png');
}

async function captureCurrentVideoFrame(videoId: string): Promise<{ dataUrl: string; filename: string }> {
  const video = getMainVideoElement();
  if (!video) {
    throw new Error('Video element not found');
  }

  try {
    const dataUrl = await captureRawVideoFrame(video);
    return {
      dataUrl,
      filename: buildScreenshotFilename(videoId),
    };
  } catch (error) {
    console.warn('[YouTube Rewind] Direct frame capture failed, falling back to clean tab capture', error);
  }

  const rect = getVisibleVideoRect(video);
  if (!rect) {
    throw new Error('Video is outside the viewport');
  }

  document.documentElement.dataset.ytrCleanVideoCapture = 'true';

  try {
    await waitForAnimationFrame();
    await waitForAnimationFrame();
    const tabCapture = await captureVisibleTab();
    const dataUrl = await cropDataUrlToRect(tabCapture, rect);
    return {
      dataUrl,
      filename: buildScreenshotFilename(videoId),
    };
  } finally {
    delete document.documentElement.dataset.ytrCleanVideoCapture;
  }
}

// --- Image overlay (shared by thumbnail preview + screenshot) ---

function renderOverlayStrokes(
  ctx: CanvasRenderingContext2D,
  strokes: OverlayStroke[],
  width: number,
  height: number,
): void {
  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  for (const stroke of strokes) {
    if (!stroke.points.length) continue;

    const size = Math.max(1, stroke.sizeRatio * Math.min(width, height));
    ctx.save();
    ctx.globalCompositeOperation = stroke.tool === 'eraser' ? 'destination-out' : 'source-over';
    ctx.strokeStyle = stroke.color;
    ctx.fillStyle = stroke.color;
    ctx.lineWidth = size;

    const first = {
      x: stroke.points[0].x * width,
      y: stroke.points[0].y * height,
    };

    if (stroke.points.length === 1) {
      ctx.beginPath();
      ctx.arc(first.x, first.y, size / 2, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      continue;
    }

    ctx.beginPath();
    ctx.moveTo(first.x, first.y);
    for (const point of stroke.points.slice(1)) {
      ctx.lineTo(point.x * width, point.y * height);
    }
    ctx.stroke();
    ctx.restore();
  }

  ctx.restore();
}

async function buildOverlayExportDataUrl(item: OverlayGalleryItem, strokes: OverlayStroke[]): Promise<string> {
  if (!strokes.length) return item.src;

  const image = await loadImage(item.src);
  const canvas = document.createElement('canvas');
  canvas.width = image.naturalWidth || image.width;
  canvas.height = image.naturalHeight || image.height;

  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Canvas unavailable');

  const overlayCanvas = document.createElement('canvas');
  overlayCanvas.width = canvas.width;
  overlayCanvas.height = canvas.height;
  const overlayCtx = overlayCanvas.getContext('2d');
  if (!overlayCtx) throw new Error('Canvas unavailable');

  ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
  renderOverlayStrokes(overlayCtx, strokes, canvas.width, canvas.height);
  ctx.drawImage(overlayCanvas, 0, 0);
  return canvas.toDataURL('image/png');
}

type ConfirmDialogOptions = {
  title: string;
  message: string;
  confirmText: string;
  cancelText: string;
};

function showYtrConfirmDialog(options: ConfirmDialogOptions): Promise<boolean> {
  const existing = document.querySelector('.ytr-confirm');
  if (existing) existing.remove();

  return new Promise((resolve) => {
    const root = document.createElement('div');
    root.className = 'ytr-confirm';
    const backdrop = createHtmlElement('div', 'ytr-confirm-backdrop');
    const card = createHtmlElement('div', 'ytr-confirm-card');
    card.setAttribute('role', 'alertdialog');
    card.setAttribute('aria-modal', 'true');
    card.setAttribute('aria-labelledby', 'ytr-confirm-title');
    card.setAttribute('aria-describedby', 'ytr-confirm-message');

    const title = createHtmlElement('div', 'ytr-confirm-title', options.title);
    title.id = 'ytr-confirm-title';
    const message = createHtmlElement('div', 'ytr-confirm-message', options.message);
    message.id = 'ytr-confirm-message';
    const actions = createHtmlElement('div', 'ytr-confirm-actions');
    const cancelButton = createHtmlElement('button', 'ytr-confirm-btn ytr-confirm-btn-secondary', options.cancelText);
    cancelButton.type = 'button';
    const confirmButton = createHtmlElement('button', 'ytr-confirm-btn ytr-confirm-btn-primary', options.confirmText);
    confirmButton.type = 'button';
    actions.append(cancelButton, confirmButton);
    card.append(title, message, actions);
    root.append(backdrop, card);

    const finish = (value: boolean) => {
      root.remove();
      document.removeEventListener('keydown', onKeyDown, true);
      resolve(value);
    };

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        finish(false);
      }
      if (event.key === 'Enter') {
        const target = document.activeElement as HTMLElement | null;
        if (target?.classList.contains('ytr-confirm-btn-secondary')) return;
        event.preventDefault();
        finish(true);
      }
    };

    backdrop.addEventListener('click', () => finish(false));
    cancelButton.addEventListener('click', () => finish(false));
    confirmButton.addEventListener('click', () => finish(true));

    document.body.appendChild(root);
    document.addEventListener('keydown', onKeyDown, true);
    confirmButton.focus();
  });
}

